insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:6-96b5e138fd','admin-navarra',6,'Cuando el Gobierno impugna ante el Tribunal Constitucional disposiciones y resoluciones de las CCAA, la impugnación produce la suspensión, que el Tribunal debe ratificar o levantar en un plazo no superior a:','["3 meses", "5 meses", "2 meses", "6 meses"]'::jsonb,1,'Art. 161.2 CE','La suspensión es automática y el Tribunal la ratifica o levanta en un plazo no superior a cinco meses.',null),
('admin-navarra:6-56653db317','admin-navarra',6,'La cuestión de inconstitucionalidad la plantea:','["El Ministerio Fiscal en cualquier proceso, antes de que se dicte sentencia firme por el órgano judicial", "Un órgano judicial que considere que una norma con rango de ley aplicable al caso pueda ser contraria a la Constitución", "El Defensor del Pueblo cuando una ley vulnere derechos fundamentales, en el plazo de tres meses", "Cualquier ciudadano afectado por una norma con rango de ley que considere inconstitucional, en el plazo de tres meses desde su publicación"]'::jsonb,1,'Art. 163 CE','En ningún caso tiene efectos suspensivos.',null),
('admin-navarra:6-ba5a97ce2b','admin-navarra',6,'Las sentencias del Tribunal Constitucional tienen el valor de cosa juzgada:','["A partir del día siguiente de su publicación, y no cabe recurso alguno contra ellas", "A partir de su notificación a las partes, y contra ellas cabe recurso de súplica ante el Pleno", "A partir de su publicación en el BOE con los votos particulares, pero cabe recurso ante el Tribunal Supremo", "A partir de los veinte días de su publicación, y no cabe recurso contra ellas"]'::jsonb,0,'Art. 164.1 CE','Se publican en el BOE con los votos particulares, si los hubiere.',null),
('admin-navarra:6-1ca83aa348','admin-navarra',6,'¿Qué órgano NO puede proponer magistrados del Tribunal Constitucional?','["El Gobierno", "El Senado", "El Consejo General del Poder Judicial", "El Tribunal Supremo"]'::jsonb,3,'Art. 159.1 CE','Proponen el Congreso, el Senado, el Gobierno y el CGPJ.',null),
('admin-navarra:6-6f5db1e216','admin-navarra',6,'¿Quiénes pueden ejercer la iniciativa de reforma constitucional?','["Gobierno, Congreso, Senado, Asambleas de las CCAA y la iniciativa popular con 500.000 firmas", "Gobierno y Congreso, y el Senado solo a propuesta de las Asambleas de las CCAA", "Gobierno, Congreso y Senado, y también la iniciativa popular respaldada por un millón de firmas", "Gobierno, Congreso, Senado y Asambleas de las CCAA, pero no la iniciativa popular"]'::jsonb,3,'Art. 166 CE','La iniciativa se ejerce según los apartados 1 y 2 del art. 87, que no incluyen la iniciativa popular del art. 87.3.',null),
('admin-navarra:6-b15ca40094','admin-navarra',6,'Por el procedimiento ordinario del art. 167 CE, los proyectos de reforma constitucional deben aprobarse por:','["Mayoría absoluta de cada una de las Cámaras", "Mayoría de tres quintos de cada una de las Cámaras", "Mayoría de dos tercios de cada una de las Cámaras", "Mayoría de tres quintos del Congreso y absoluta del Senado"]'::jsonb,1,'Art. 167.1 CE','Si no hay acuerdo entre las Cámaras, se intenta obtenerlo mediante una comisión de composición paritaria de Diputados y Senadores.',null),
('admin-navarra:6-d4365e4d5d','admin-navarra',6,'Si no se logra la aprobación de una reforma por el procedimiento del art. 167.1 CE, el Congreso podrá aprobarla:','["Por mayoría absoluta, siempre que el texto hubiera obtenido la mayoría de tres quintos del Senado", "Por mayoría de dos tercios, siempre que el texto hubiera obtenido la mayoría absoluta del Senado", "Por mayoría de dos tercios, aunque el Senado haya rechazado el texto por mayoría absoluta", "Por mayoría de tres quintos, siempre que el texto se someta después a referéndum obligatorio de todos los españoles"]'::jsonb,1,'Art. 167.2 CE','Así lo prevé el art. 167.2 CE.',null),
('admin-navarra:6-3535b541c6','admin-navarra',6,'En la reforma por el procedimiento del art. 167 CE, el referéndum es:','["Facultativo: se celebra si lo solicita, en los 15 días siguientes a la aprobación, una décima parte de los miembros de cualquiera de las Cámaras", "Facultativo: se celebra si lo solicita, en los 15 días siguientes, la mayoría absoluta del Congreso", "Obligatorio en todo caso, y se celebra en los 15 días siguientes a la aprobación del texto por las Cortes Generales, con independencia de lo que soliciten las Cámaras", "Facultativo: se celebra si lo solicitan, en los 30 días siguientes, 50 Diputados o 50 Senadores"]'::jsonb,0,'Art. 167.3 CE','En el procedimiento agravado del art. 168, en cambio, el referéndum es obligatorio.',null),
('admin-navarra:6-9d01df514a','admin-navarra',6,'La revisión total de la Constitución o una parcial que afecte al Título preliminar, a la Sección 1.ª del Capítulo II del Título I o al Título II exige:','["Aprobación por tres quintos de cada Cámara, disolución inmediata de las Cortes y referéndum facultativo", "Aprobación por mayoría absoluta de cada Cámara, disolución inmediata de las Cortes y referéndum obligatorio", "Aprobación por dos tercios de cada Cámara, disolución inmediata de las Cortes, ratificación por las nuevas Cámaras y referéndum", "Aprobación por dos tercios del Congreso y mayoría absoluta del Senado, y después referéndum obligatorio"]'::jsonb,2,'Art. 168 CE','Las nuevas Cámaras deben ratificar la decisión, estudiar el nuevo texto y aprobarlo por mayoría de dos tercios de ambas.',null),
('admin-navarra:6-26dfa04ca3','admin-navarra',6,'¿Cuándo no podrá iniciarse la reforma constitucional?','["Durante la regencia o la minoría de edad del Rey", "Durante el último año de la legislatura o mientras haya un proceso electoral convocado", "En tiempo de guerra o de vigencia de alguno de los estados del art. 116", "Mientras esté pendiente de resolver un recurso de inconstitucionalidad contra una ley orgánica"]'::jsonb,2,'Art. 169 CE','Los estados del art. 116 son los de alarma, excepción y sitio.',null),
('admin-navarra:6-b5253a7815','admin-navarra',6,'Según el art. 66.2 CE, las Cortes Generales:','["Ejercen la potestad legislativa, elaboran los Presupuestos y dirigen la política exterior", "Ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución", "Aprueban los Presupuestos y controlan al Gobierno, pero la potestad legislativa es del Congreso", "Ejercen la potestad legislativa y reglamentaria del Estado y dirigen la Administración General del Estado"]'::jsonb,1,'Art. 66.2 CE','Las Cortes representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado (art. 66.1).',null),
('admin-navarra:6-bf842b0569','admin-navarra',6,'Según el art. 67 CE, los miembros de las Cortes Generales:','["Están ligados por el mandato del partido con el que concurrieron a las elecciones, salvo en votaciones secretas", "No están ligados por mandato imperativo", "Pueden ser a la vez Diputados y Senadores si lo autoriza la Mesa", "Pueden acumular el acta de Diputado con la de una Asamblea autonómica"]'::jsonb,1,'Art. 67.2 CE','Nadie puede ser miembro de las dos Cámaras simultáneamente ni acumular el acta de una Asamblea de CA con la de Diputado al Congreso (art. 67.1).',null),
('admin-navarra:6-b8abb64260','admin-navarra',6,'¿Entre qué número mínimo y máximo de Diputados puede componerse el Congreso según la Constitución?','["Entre 250 y 400", "Entre 350 y 400", "Entre 300 y 350", "Entre 300 y 400"]'::jsonb,3,'Art. 68.1 CE','La Constitución fija la horquilla y la LOREG concreta el número en 350.',null),
('admin-navarra:6-e8948b8c69','admin-navarra',6,'Según el art. 68 CE, la circunscripción electoral para el Congreso es:','["La Comunidad Autónoma, y Ceuta y Melilla están representadas cada una por dos Diputados", "El municipio de más de 50.000 habitantes y, en los demás casos, la provincia", "La provincia, y Ceuta y Melilla están representadas cada una por un Diputado", "La provincia, y Ceuta y Melilla están representadas cada una por dos Diputados"]'::jsonb,2,'Art. 68.2 CE','La elección se verifica en cada circunscripción atendiendo a criterios de representación proporcional (art. 68.3).',null),
('admin-navarra:6-ffd54c909c','admin-navarra',6,'Las elecciones generales deben tener lugar:','["Entre los 45 y 90 días desde la terminación del mandato", "En los 60 días siguientes a la disolución, sin plazo mínimo", "Entre los 30 y 60 días desde la terminación del mandato", "Entre los 15 y 30 días desde la terminación del mandato"]'::jsonb,2,'Art. 68.6 CE','El Congreso electo debe ser convocado dentro de los 25 días siguientes a la celebración de las elecciones.',null),
('admin-navarra:6-10c831deb2','admin-navarra',6,'El Congreso electo deberá ser convocado dentro de los:','["25 días siguientes a la celebración de las elecciones", "30 días siguientes a la celebración de las elecciones", "15 días siguientes a la proclamación de los electos", "25 días siguientes a la publicación de los resultados en el BOE"]'::jsonb,0,'Art. 68.6 CE','Así lo dispone el art. 68.6 CE.',null),
('admin-navarra:6-592c3dea88','admin-navarra',6,'¿Cuántos Senadores elige cada una de las ciudades de Ceuta y Melilla?','["1", "3", "2", "4"]'::jsonb,2,'Art. 69.4 CE','Las provincias eligen 4 Senadores cada una por sufragio universal, libre, igual, directo y secreto.',null),
('admin-navarra:6-7bcf152449','admin-navarra',6,'Las Comunidades Autónomas designan para el Senado:','["Un Senador por cada 500.000 habitantes de su territorio", "Dos Senadores y otro más por cada millón de habitantes de su territorio", "Un Senador por cada provincia de la Comunidad", "Un Senador y otro más por cada millón de habitantes de su territorio"]'::jsonb,3,'Art. 69.5 CE','La designación corresponde a la Asamblea legislativa o, en su defecto, al órgano colegiado superior de la CA, asegurando la representación proporcional.',null),
('admin-navarra:6-54cc103389','admin-navarra',6,'Durante su mandato, los Diputados y Senadores solo podrán ser detenidos:','["Con autorización previa del Tribunal Supremo, salvo flagrante delito", "En ningún caso, mientras dure su mandato", "En caso de flagrante delito", "En caso de delito grave, con autorización del Presidente de la Cámara"]'::jsonb,2,'Art. 71.2 CE','Gozan de inmunidad: no pueden ser inculpados ni procesados sin la previa autorización de la Cámara respectiva.',null),
('admin-navarra:6-d79e64a21b','admin-navarra',6,'¿Qué órgano es competente en las causas contra Diputados y Senadores?','["El Tribunal Superior de Justicia de su circunscripción", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional, en única instancia"]'::jsonb,2,'Art. 71.3 CE','Así lo establece el art. 71.3 CE.',null),
('admin-navarra:6-0cb121655f','admin-navarra',6,'Los Reglamentos de las Cámaras y su reforma se aprueban:','["Por mayoría absoluta de las Cortes reunidas en sesión conjunta", "Por mayoría de tres quintos, en una votación final sobre su totalidad", "Por mayoría absoluta, en una votación final sobre su totalidad", "Por mayoría simple, artículo por artículo"]'::jsonb,2,'Art. 72.1 CE','Las Cámaras establecen sus propios Reglamentos y aprueban autónomamente sus presupuestos.',null),
('admin-navarra:6-c819def67b','admin-navarra',6,'Las sesiones conjuntas de ambas Cámaras están presididas por:','["El Presidente de mayor edad", "El Rey", "El Presidente del Congreso", "El Presidente del Senado"]'::jsonb,2,'Art. 72.2 CE','Se rigen por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.',null),
('admin-navarra:6-3a0bf91027','admin-navarra',6,'¿Cuáles son los períodos ordinarios de sesiones de las Cámaras?','["De octubre a diciembre y de febrero a julio", "De septiembre a junio, sin interrupción", "De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio"]'::jsonb,2,'Art. 73.1 CE','Las Cámaras se reúnen anualmente en dos períodos ordinarios de sesiones.',null),
('admin-navarra:6-06e5a978e9','admin-navarra',6,'Las sesiones extraordinarias de las Cámaras pueden celebrarse a petición de:','["El Gobierno o la Diputación Permanente, pero no de los miembros de las Cámaras", "El Rey, el Gobierno o una quinta parte de los miembros de cualquiera de las Cámaras", "El Gobierno, la Diputación Permanente o la mayoría absoluta de los miembros de cualquiera de las Cámaras", "El Presidente del Gobierno, la Mesa del Congreso o la mitad de los grupos parlamentarios"]'::jsonb,2,'Art. 73.2 CE','Se convocan sobre un orden del día determinado y se clausuran una vez que este haya sido agotado.',null),
('admin-navarra:6-4798e46711','admin-navarra',6,'¿Cuál de estas materias NO puede delegar el Pleno en las Comisiones Legislativas Permanentes?','["Una ley ordinaria sobre carreteras del Estado", "Los Presupuestos Generales del Estado", "Una ley sobre el régimen de las asociaciones de consumidores", "Una ley sobre el régimen de los colegios profesionales"]'::jsonb,1,'Art. 75.3 CE','Tampoco la reforma constitucional, las cuestiones internacionales, ni las leyes orgánicas y de bases.',null),
('admin-navarra:6-7cf30249a4','admin-navarra',6,'Las conclusiones de las comisiones de investigación de las Cámaras:','["Se remiten siempre al Tribunal Supremo, que decide si abre causa", "No son vinculantes para los Tribunales ni afectan a las resoluciones judiciales", "Vinculan a la Administración, que debe ejecutarlas en el plazo de un mes", "Son vinculantes para los Tribunales cuando se refieran a hechos delictivos"]'::jsonb,1,'Art. 76.1 CE','El resultado puede comunicarse al Ministerio Fiscal para el ejercicio de las acciones oportunas, y es obligatorio comparecer a requerimiento de las Cámaras (art. 76.2).',null),
('admin-navarra:6-849b70a65d','admin-navarra',6,'¿Cuántos miembros como mínimo tiene la Diputación Permanente de cada Cámara?','["15", "25", "30", "21"]'::jsonb,3,'Art. 78.1 CE','Representan a los grupos parlamentarios en proporción a su importancia numérica y la preside el Presidente de la Cámara.',null),
('admin-navarra:6-40109fed32','admin-navarra',6,'Para adoptar acuerdos, las Cámaras deben estar reunidas reglamentariamente y con asistencia de:','["La mayoría de sus miembros", "Cualquier número de miembros", "Dos tercios de sus miembros", "Un tercio de sus miembros"]'::jsonb,0,'Art. 79.1 CE','Los acuerdos se aprueban, en general, por mayoría de los miembros presentes (art. 79.2).',null),
('admin-navarra:6-5177ace4d2','admin-navarra',6,'Según el art. 79.3 CE, el voto de Senadores y Diputados:','["Es personal, pero puede delegarse en otro miembro del mismo grupo", "Es personal, pero el portavoz puede emitirlo por todo el grupo", "Es indelegable, salvo enfermedad acreditada ante la Mesa", "Es personal e indelegable"]'::jsonb,3,'Art. 79.3 CE','Así lo dispone el art. 79.3 CE.',null),
('admin-navarra:6-49e8a875c0','admin-navarra',6,'Las sesiones plenarias de las Cámaras serán públicas:','["Salvo acuerdo en contrario de cada Cámara por mayoría absoluta o con arreglo al Reglamento", "Salvo acuerdo en contrario de la Mesa de cada Cámara", "En todo caso, sin excepción", "Salvo que lo solicite el Gobierno por razones de seguridad nacional, aunque no lo acuerde la Cámara"]'::jsonb,0,'Art. 80 CE','Así lo dispone el art. 80 CE.',null),
('admin-navarra:6-e57922436a','admin-navarra',6,'¿Quién tiene la iniciativa legislativa según el art. 87.1 CE?','["El Gobierno y el Congreso, pero no el Senado", "El Gobierno, el Congreso, el Senado y el Consejo General del Poder Judicial", "El Congreso y el Senado, y el Gobierno solo en materia presupuestaria", "El Gobierno, el Congreso y el Senado"]'::jsonb,3,'Art. 87.1 CE','Las Asambleas de las CCAA pueden solicitar al Gobierno la adopción de un proyecto o remitir a la Mesa del Congreso una proposición (art. 87.2), y existe la iniciativa popular (art. 87.3).',null),
('admin-navarra:6-13ed5e62b1','admin-navarra',6,'¿Cuántas firmas acreditadas exige como mínimo la iniciativa legislativa popular?','["100.000", "1.000.000", "250.000", "500.000"]'::jsonb,3,'Art. 87.3 CE','No procede en materias propias de ley orgánica, tributarias, de carácter internacional ni en lo relativo a la prerrogativa de gracia.',null),
('admin-navarra:6-64715cb682','admin-navarra',6,'Una Asamblea de Comunidad Autónoma que remite una proposición de ley a la Mesa del Congreso puede delegar su defensa ante esta Cámara en:','["Un máximo de tres miembros de la Asamblea", "Los Senadores designados por la Comunidad", "Un máximo de cinco miembros de la Asamblea", "El Presidente de la Comunidad Autónoma"]'::jsonb,0,'Art. 87.2 CE','Así lo dispone el art. 87.2 CE.',null),
('admin-navarra:6-246a901664','admin-navarra',6,'¿En qué plazo puede el Senado oponer su veto o introducir enmiendas a un proyecto aprobado por el Congreso?','["Dos meses desde la aprobación en el Congreso, o un mes si el proyecto se declara urgente", "Dos meses desde el día de la recepción del texto, o veinte días naturales si el proyecto se declara urgente", "Un mes desde la recepción del texto, o diez días naturales si el proyecto se declara urgente", "Tres meses desde la recepción del texto, sin reducción por urgencia"]'::jsonb,1,'Art. 90.2 y 90.3 CE','El veto debe aprobarse por mayoría absoluta del Senado.',null),
('admin-navarra:6-92cd1d01cb','admin-navarra',6,'El veto del Senado puede ser levantado por el Congreso:','["Por mayoría de tres quintos, o por mayoría absoluta una vez transcurrido un mes", "Por mayoría de dos tercios, en sesión conjunta con el Senado", "Por mayoría absoluta, o por mayoría simple una vez transcurridos dos meses desde su interposición", "Por mayoría simple en todo caso, en una nueva votación"]'::jsonb,2,'Art. 90.2 CE','Así lo dispone el art. 90.2 CE.',null),
('admin-navarra:6-6d3d69e905','admin-navarra',6,'El Rey sancionará las leyes aprobadas por las Cortes Generales en el plazo de:','["20 días", "10 días", "30 días", "15 días"]'::jsonb,3,'Art. 91 CE','Las promulgará y ordenará su inmediata publicación.',null),
('admin-navarra:6-cda7e74b2e','admin-navarra',6,'El referéndum consultivo sobre decisiones políticas de especial trascendencia es convocado por:','["El Presidente del Gobierno, previa autorización de las Cortes Generales por mayoría absoluta", "El Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso", "El Rey, a propuesta del Congreso de los Diputados por mayoría de tres quintos", "El Gobierno, previa deliberación del Consejo de Ministros y dictamen del Consejo de Estado"]'::jsonb,1,'Art. 92.2 CE','Lo regula la LO 2/1980.',null),
('admin-navarra:6-2728cd2842','admin-navarra',6,'Los tratados por los que se atribuya a una organización internacional el ejercicio de competencias derivadas de la Constitución se autorizan:','["Por acuerdo del Consejo de Ministros", "Mediante ley orgánica", "Mediante referéndum", "Mediante ley ordinaria"]'::jsonb,1,'Art. 93 CE','Así se autorizó la adhesión de España a las Comunidades Europeas.',null),
('admin-navarra:6-9cf705a76e','admin-navarra',6,'La moción de censura debe ser propuesta, al menos, por:','["Un grupo parlamentario, e incluir un candidato a la Presidencia del Gobierno", "La décima parte de los Diputados, sin necesidad de proponer candidato", "La quinta parte de los Diputados, e incluir un programa de gobierno alternativo", "La décima parte de los Diputados, e incluir un candidato a la Presidencia del Gobierno"]'::jsonb,3,'Art. 113.2 CE','Se adopta por mayoría absoluta del Congreso (art. 113.1).',null),
('admin-navarra:6-09152f0ed1','admin-navarra',6,'La moción de censura no podrá ser votada hasta que transcurran:','["Cinco días desde su presentación", "Dos días desde su presentación", "Tres días desde su presentación", "Diez días desde su presentación"]'::jsonb,0,'Art. 113.3 CE','En los dos primeros días de ese plazo pueden presentarse mociones alternativas.',null),
('admin-navarra:6-6c11e858f1','admin-navarra',6,'Si la moción de censura no es aprobada, sus signatarios:','["No podrán presentar otra durante un año", "Podrán presentar otra pasados tres meses", "No podrán presentar otra durante el mismo período de sesiones", "No podrán presentar otra durante el resto de la legislatura"]'::jsonb,2,'Art. 113.4 CE','Así lo dispone el art. 113.4 CE.',null),
('admin-navarra:6-87129a9f3f','admin-navarra',6,'La confianza se entiende otorgada cuando vote a favor:','["La mayoría absoluta de los Diputados", "La mayoría absoluta de cada Cámara", "Las tres quintas partes de los Diputados", "La mayoría simple de los Diputados"]'::jsonb,3,'Art. 112 CE','El Presidente plantea la cuestión de confianza, previa deliberación del Consejo de Ministros, sobre su programa o una declaración de política general.',null),
('admin-navarra:6-cbc1df26c6','admin-navarra',6,'Según el art. 115 CE, la disolución de las Cámaras NO puede acordarse:','["Durante los dos primeros años de la legislatura, salvo que lo autorice el Congreso por mayoría absoluta", "Cuando esté en trámite una moción de censura, ni antes de que transcurra un año desde la anterior, salvo lo dispuesto en el art. 99.5", "Cuando esté en trámite una cuestión de confianza o durante el período de sesiones", "Durante el estado de alarma ni antes de que transcurran seis meses desde la anterior"]'::jsonb,1,'Art. 115.2 y 115.3 CE','La disolución la propone el Presidente, previa deliberación del Consejo de Ministros y bajo su exclusiva responsabilidad.',null),
('admin-navarra:6-005018ff47','admin-navarra',6,'Según el art. 54 CE, el Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros para supervisar a la Administración", "Alto comisionado de las Cortes Generales, designado por estas para la defensa de los derechos del Título I", "Alto comisionado de las Cortes Generales, designado por el Rey a propuesta del Congreso", "Órgano del Poder Judicial encargado de la defensa de los derechos fundamentales"]'::jsonb,1,'Art. 54 CE','Puede supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.',null),
('admin-navarra:6-5468f50f3a','admin-navarra',6,'Según el art. 117.1 CE, la justicia emana del pueblo y se administra:','["En nombre del pueblo español por Jueces, Magistrados y Fiscales integrantes del poder judicial", "En nombre del Rey por el Consejo General del Poder Judicial", "En nombre de las Cortes Generales por Jueces y Magistrados", "En nombre del Rey por Jueces y Magistrados integrantes del poder judicial"]'::jsonb,3,'Art. 117.1 CE','Los Jueces y Magistrados son independientes, inamovibles, responsables y están sometidos únicamente al imperio de la ley.',null),
('admin-navarra:6-57fe84f3e3','admin-navarra',6,'¿Cuál de estas notas NO atribuye el art. 117.1 CE a los Jueces y Magistrados?','["Responsabilidad", "Inamovilidad", "Independencia", "Jerarquía"]'::jsonb,3,'Art. 117.1 CE','Son independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley. La dependencia jerárquica es un principio del Ministerio Fiscal (art. 124.2).',null),
('admin-navarra:6-e53728584c','admin-navarra',6,'Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados:','["En ningún caso antes de cumplir la edad de jubilación forzosa", "Sino por alguna de las causas y con las garantías previstas en la ley", "Sino por sentencia firme de la Sala de lo Penal del Tribunal Supremo, a instancia del Ministerio Fiscal", "Sino por acuerdo del Ministerio de Justicia, oído el interesado"]'::jsonb,1,'Art. 117.2 CE','Es la garantía de inamovilidad.',null),
('admin-navarra:6-b67d6a26e0','admin-navarra',6,'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde:','["A los Juzgados y Tribunales y, en materia administrativa, a los órganos de la Administración", "A los Juzgados y Tribunales, salvo la ejecución, que corresponde al Gobierno", "Exclusivamente a los Juzgados y Tribunales determinados por las leyes", "Al Consejo General del Poder Judicial y a los Juzgados y Tribunales"]'::jsonb,2,'Art. 117.3 CE','Se ejerce en todo tipo de procesos, según las normas de competencia y procedimiento que las leyes establezcan.',null),
('admin-navarra:6-299428d77a','admin-navarra',6,'Según el art. 117.6 CE, los Tribunales de excepción:','["Pueden crearse por ley orgánica", "Están prohibidos", "Solo pueden crearse durante el estado de sitio", "Dependen del Tribunal Supremo"]'::jsonb,1,'Art. 117.6 CE','La ley regula la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio (art. 117.5).',null),
('admin-navarra:6-1f90edfe18','admin-navarra',6,'La justicia será gratuita, según el art. 119 CE:','["Solo para quienes acrediten insuficiencia de recursos, sin otros supuestos", "Solo en los procesos penales y en los procesos laborales", "Cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar", "Siempre, para todos los ciudadanos españoles y para los extranjeros residentes legalmente en España, en cualquier proceso"]'::jsonb,2,'Art. 119 CE','Así lo dispone el art. 119 CE.',null),
('admin-navarra:6-8ea81f3de9','admin-navarra',6,'Según el art. 120 CE, el procedimiento judicial:','["Será oral en todo caso y en todas las jurisdicciones", "Será secreto salvo en el acto del juicio", "Será predominantemente oral, sobre todo en materia criminal", "Será predominantemente escrito, salvo en materia criminal, en la que será oral"]'::jsonb,2,'Art. 120.2 CE','Las actuaciones judiciales son públicas, con las excepciones que prevean las leyes de procedimiento (art. 120.1).',null),
('admin-navarra:6-c19d6e9d2b','admin-navarra',6,'Las sentencias, según el art. 120.3 CE:','["Se pronunciarán en audiencia pública solo en materia penal", "Se notificarán por escrito y no se pronuncian en audiencia pública", "Serán motivadas solo cuando sean condenatorias", "Serán siempre motivadas y se pronunciarán en audiencia pública"]'::jsonb,3,'Art. 120.3 CE','Así lo dispone el art. 120.3 CE.',null),
('admin-navarra:6-3754186ccb','admin-navarra',6,'Los daños causados por error judicial y los que sean consecuencia del funcionamiento anormal de la Administración de Justicia:','["Darán derecho a una indemnización a cargo del Estado, conforme a la ley", "Darán derecho a indemnización a cargo del Consejo General del Poder Judicial", "No darán derecho a indemnización, salvo que exista dolo", "Darán derecho a una indemnización a cargo del juez o magistrado responsable"]'::jsonb,0,'Art. 121 CE','Así lo dispone el art. 121 CE.',null),
('admin-navarra:6-152182f368','admin-navarra',6,'¿Cuál es el órgano de gobierno del Poder Judicial?','["El Tribunal Constitucional, a través de su Pleno", "El Tribunal Supremo", "El Consejo General del Poder Judicial", "El Ministerio de Justicia"]'::jsonb,2,'Art. 122.2 CE','La ley orgánica establece su estatuto, régimen de incompatibilidades y funciones, en particular en nombramientos, ascensos, inspección y régimen disciplinario.',null),
('admin-navarra:6-d0b265a728','admin-navarra',6,'Según el art. 122.3 CE, el Consejo General del Poder Judicial está integrado por:','["El Ministro de Justicia, que lo preside, y veinte miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cuatro años", "El Presidente del Tribunal Supremo, que lo preside, y doce miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cinco años"]'::jsonb,3,'Art. 122.3 CE','De los veinte vocales, doce son Jueces y Magistrados y ocho se nombran a propuesta de las Cámaras.',null),
('admin-navarra:6-f4d6ece69f','admin-navarra',6,'De los veinte vocales del CGPJ, ¿cuántos se eligen entre Jueces y Magistrados de todas las categorías judiciales?','["12", "8", "10", "16"]'::jsonb,0,'Art. 122.3 CE','Los otros ocho los proponen el Congreso (cuatro) y el Senado (cuatro), por mayoría de tres quintos.',null),
('admin-navarra:6-31009b850a','admin-navarra',6,'Los vocales del CGPJ propuestos por las Cámaras se eligen entre:','["Magistrados del Tribunal Supremo con más de quince años de antigüedad en la carrera", "Abogados y otros juristas de reconocida competencia con más de quince años de ejercicio en su profesión", "Abogados y otros juristas de reconocida competencia con más de diez años de ejercicio en su profesión", "Catedráticos de Derecho y fiscales con más de veinte años de ejercicio profesional"]'::jsonb,1,'Art. 122.3 CE','Cuatro a propuesta del Congreso y cuatro a propuesta del Senado, elegidos en ambos casos por mayoría de tres quintos.',null),
('admin-navarra:6-9ab99b7c24','admin-navarra',6,'Según el art. 123 CE, el Tribunal Supremo:','["Es el órgano de gobierno del Poder Judicial y el superior en todos los órdenes", "Es el órgano jurisdiccional superior en todos los órdenes, incluida la materia de garantías constitucionales y el recurso de amparo", "Es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales", "Es el órgano jurisdiccional superior solo en el orden penal y en el contencioso-administrativo"]'::jsonb,2,'Art. 123.1 CE','Tiene jurisdicción en toda España. En garantías constitucionales, el órgano superior es el Tribunal Constitucional.',null),
('admin-navarra:6-0e83787279','admin-navarra',6,'El Presidente del Tribunal Supremo será nombrado por el Rey:','["A propuesta del Gobierno, oído el Consejo General del Poder Judicial y la Sala de Gobierno del propio Tribunal", "A propuesta del Consejo General del Poder Judicial, en la forma que determine la ley", "A propuesta de la Sala de Gobierno del propio Tribunal Supremo", "A propuesta del Congreso de los Diputados por mayoría de tres quintos"]'::jsonb,1,'Art. 123.2 CE','Así lo dispone el art. 123.2 CE.',null),
('admin-navarra:6-1506495ef5','admin-navarra',6,'Según el art. 152.1 CE, el Tribunal Superior de Justicia:','["Culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo", "Es el órgano jurisdiccional superior en todos los órdenes dentro de la Comunidad, sin que quepa recurso ante el Tribunal Supremo", "Es el órgano de gobierno de los jueces de la Comunidad Autónoma", "Depende del Gobierno autonómico, que nombra a su Presidente"]'::jsonb,0,'Art. 152.1 CE','Las sucesivas instancias procesales se agotan ante órganos radicados en el mismo territorio de la CA en que esté el órgano competente en primera instancia.',null),
('admin-navarra:6-3688c16bc8','admin-navarra',6,'Según el art. 124 CE, el Ministerio Fiscal ejerce sus funciones conforme a los principios de:','["Independencia e inamovilidad, con sujeción en todo caso a los de legalidad y oportunidad", "Unidad de actuación y dependencia jerárquica, con sujeción en todo caso a los de legalidad e imparcialidad", "Jerarquía y oportunidad, con sujeción a los de legalidad e imparcialidad", "Unidad de actuación y autonomía funcional, con sujeción a las instrucciones del Ministerio de Justicia en cada caso"]'::jsonb,1,'Art. 124.2 CE','Lo hace por medio de órganos propios.',null),
('admin-navarra:6-318e23697f','admin-navarra',6,'¿Quién nombra al Fiscal General del Estado?','["El Gobierno, a propuesta del Ministro de Justicia, oído el Congreso", "El Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial", "El Rey, a propuesta del Consejo General del Poder Judicial, oído el Gobierno", "El Congreso de los Diputados, por mayoría de tres quintos"]'::jsonb,1,'Art. 124.4 CE','Así lo dispone el art. 124.4 CE.',null),
('admin-navarra:6-327ad58bd0','admin-navarra',6,'Según el art. 124.1 CE, ¿cuál de estas es una misión del Ministerio Fiscal?','["Dirigir la Administración de Justicia, nombrar a los jueces y magistrados y ejercer sobre ellos la potestad disciplinaria, por delegación del CGPJ", "Juzgar los delitos cometidos por los miembros del Gobierno", "Ejercer la potestad disciplinaria sobre jueces y magistrados", "Promover la acción de la justicia en defensa de la legalidad, los derechos de los ciudadanos y el interés público tutelado por la ley"]'::jsonb,3,'Art. 124.1 CE','También velar por la independencia de los Tribunales y procurar ante ellos la satisfacción del interés social.',null),
('admin-navarra:6-c15880e048','admin-navarra',6,'Según el art. 125 CE, los ciudadanos podrán participar en la Administración de Justicia mediante:','["La acción popular y la elección directa de los jueces de paz en todos los municipios, y la institución del Jurado en los procesos civiles y penales que determine la ley", "La acción popular, pero no la institución del Jurado", "La institución del Jurado en todos los procesos penales y civiles", "La acción popular y la institución del Jurado, en la forma y en los procesos penales que la ley determine, y en los Tribunales consuetudinarios y tradicionales"]'::jsonb,3,'Art. 125 CE','El Tribunal del Jurado se regula en la LO 5/1995.',null),
('admin-navarra:6-4cda59cbb7','admin-navarra',6,'La policía judicial depende, en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente:','["De la Audiencia Nacional", "De los Jueces, de los Tribunales y del Ministerio Fiscal", "Del Ministerio del Interior en exclusiva, a través de las Fuerzas y Cuerpos de Seguridad del Estado", "Del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 126 CE','Así lo dispone el art. 126 CE.',null),
('admin-navarra:6-9d8c05d221','admin-navarra',6,'Los Jueces y Magistrados, así como los Fiscales, mientras se hallen en activo:','["Podrán pertenecer a partidos políticos y sindicatos, pero no ocupar cargos directivos en ellos ni desempeñar otros cargos públicos", "No podrán desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos", "No podrán pertenecer a sindicatos, pero sí a partidos políticos", "Podrán desempeñar cargos públicos con autorización del CGPJ"]'::jsonb,1,'Art. 127.1 CE','La ley establece el sistema y modalidades de asociación profesional.',null),
('admin-navarra:6-cf0db2ee04','admin-navarra',6,'¿Pueden los Jueces y Magistrados en activo asociarse profesionalmente?','["No, solo pueden afiliarse a sindicatos", "Sí, la ley establece el sistema y las modalidades de asociación profesional", "Sí, pero solo a través de partidos políticos", "No, la asociación está prohibida en todo caso"]'::jsonb,1,'Art. 127.1 CE','Lo que tienen prohibido es pertenecer a partidos políticos o sindicatos.',null),
('admin-navarra:6-bd778752ae','admin-navarra',6,'Según el art. 118 CE, cumplir las sentencias y demás resoluciones firmes de los Jueces y Tribunales:','["Es obligado, así como prestar la colaboración requerida por estos en el curso del proceso y en la ejecución de lo resuelto", "Es voluntario hasta que se dicte el auto de ejecución", "Es obligado para los particulares, pero no para la Administración, que puede suspender su ejecución por razones de interés público apreciadas por el Gobierno", "Es obligado solo para las partes del proceso"]'::jsonb,0,'Art. 118 CE','Así lo dispone el art. 118 CE.',null),
('admin-navarra:6-9ce5b4d252','admin-navarra',6,'El principio de unidad jurisdiccional es, según el art. 117.5 CE:','["La base de la organización y funcionamiento de los Tribunales", "Una excepción aplicable solo a la jurisdicción militar", "La base de la organización del Ministerio Fiscal", "Un principio que rige solo en el Tribunal Supremo"]'::jsonb,0,'Art. 117.5 CE','La ley regula el ejercicio de la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio.',null),
('admin-navarra:6-253f0e9fe9','admin-navarra',6,'¿Qué ley determina la constitución, funcionamiento y gobierno de los Juzgados y Tribunales?','["La Ley de Enjuiciamiento Civil", "El Reglamento del Consejo General del Poder Judicial", "La Ley de Planta y Demarcación Judicial", "La Ley Orgánica del Poder Judicial"]'::jsonb,3,'Art. 122.1 CE','También el estatuto jurídico de los Jueces y Magistrados de carrera y del personal al servicio de la Administración de Justicia.',null),
('admin-navarra:6-73754f17e8','admin-navarra',6,'Según el art. 97 CE, el Gobierno dirige:','["La Administración civil y militar, y las Cortes dirigen la política interior y la exterior", "La política interior y exterior, la Administración civil y militar y la defensa del Estado", "La política interior y exterior y la Administración civil, pero no la militar, que corresponde al Rey", "La política interior, mientras que la exterior y la defensa corresponden al Rey como Jefe del Estado"]'::jsonb,1,'Art. 97 CE','Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.',null),
('admin-navarra:6-6777ca23ff','admin-navarra',6,'Según el art. 98.1 CE, el Gobierno se compone de:','["El Presidente, los Vicepresidentes, en su caso, los Ministros y los demás miembros que establezca la ley", "El Presidente, los Vicepresidentes, los Ministros y los Subsecretarios de cada Departamento", "El Presidente, los Vicepresidentes y los Ministros, sin que una ley pueda añadir otros miembros distintos de los citados", "El Presidente, los Ministros y los Secretarios de Estado"]'::jsonb,0,'Art. 98.1 CE','La Ley 50/1997 concreta que el Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros (art. 1.2).',null),
('admin-navarra:6-43feb2f119','admin-navarra',6,'¿Quién dirige la acción del Gobierno y coordina las funciones de los demás miembros?','["El Consejo de Ministros", "El Ministro de la Presidencia", "El Presidente", "El Vicepresidente primero"]'::jsonb,2,'Art. 98.2 CE','Sin perjuicio de la competencia y responsabilidad directa de los Ministros en su gestión.',null),
('admin-navarra:6-bf2664c044','admin-navarra',6,'Según el art. 98.3 CE, los miembros del Gobierno:','["No pueden ejercer otras funciones representativas que las propias del mandato parlamentario, ni otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna", "No pueden ser a la vez Diputados ni Senadores", "Pueden compatibilizar su cargo con otra función pública si lo autoriza el Consejo de Ministros", "Pueden ejercer actividades profesionales si no tienen relación con su Departamento"]'::jsonb,0,'Art. 98.3 CE','Por eso sí pueden ser parlamentarios a la vez.',null),
('admin-navarra:6-da01e81baf','admin-navarra',6,'Antes de proponer un candidato a la Presidencia del Gobierno, el Rey consulta:','["Al Consejo de Estado y a los presidentes de las Comunidades Autónomas", "A los representantes designados por los grupos políticos con representación parlamentaria", "Al candidato de la lista más votada, que es propuesto en todo caso", "A los Presidentes del Congreso y del Senado y al Presidente del Tribunal Constitucional, por este orden"]'::jsonb,1,'Art. 99.1 CE','La propuesta se hace a través del Presidente del Congreso.',null),
('admin-navarra:6-77728d972e','admin-navarra',6,'En la investidura, si el candidato no obtiene la mayoría absoluta del Congreso en la primera votación:','["Se somete a nueva votación 48 horas después y la confianza se entiende otorgada por mayoría simple", "Se somete a nueva votación una semana después y basta la mayoría simple", "Se somete a nueva votación 24 horas después y se exige de nuevo la mayoría absoluta de los miembros del Congreso", "Se disuelven las Cámaras y se convocan elecciones generales"]'::jsonb,0,'Art. 99.3 CE','Así lo dispone el art. 99.3 CE.',null),
('admin-navarra:6-01ee3e15a5','admin-navarra',6,'Si transcurren dos meses desde la primera votación de investidura sin que ningún candidato obtenga la confianza del Congreso:','["El Rey disuelve el Congreso, pero no el Senado, con el refrendo del Presidente del Gobierno en funciones", "El Rey nombra Presidente al candidato de la lista más votada", "El Rey disuelve ambas Cámaras y convoca nuevas elecciones con el refrendo del Presidente del Congreso", "El Congreso elige Presidente por mayoría simple sin necesidad de propuesta del Rey"]'::jsonb,2,'Art. 99.5 CE','Así lo dispone el art. 99.5 CE.',null),
('admin-navarra:6-3bec7e0a77','admin-navarra',6,'Los demás miembros del Gobierno son nombrados y separados:','["Por el Rey, previa autorización del Congreso", "Por el Consejo de Ministros", "Por el Presidente del Gobierno, dando cuenta al Congreso", "Por el Rey, a propuesta de su Presidente"]'::jsonb,3,'Art. 100 CE','Así lo dispone el art. 100 CE.',null),
('admin-navarra:6-bf0afde983','admin-navarra',6,'¿En cuál de estos casos NO cesa el Gobierno según el art. 101 CE?','["Por pérdida de la confianza parlamentaria", "Tras la celebración de elecciones generales", "Por fallecimiento de su Presidente", "Cuando dimite un Vicepresidente"]'::jsonb,3,'Art. 101.1 CE','Cesa tras las elecciones generales, por pérdida de la confianza parlamentaria y por dimisión o fallecimiento de su Presidente.',null),
('admin-navarra:6-f1ba105104','admin-navarra',6,'El Gobierno cesante:','["Es sustituido por la Comisión General de Secretarios de Estado y Subsecretarios", "Continúa en funciones durante un máximo de dos meses", "Continúa en funciones hasta la toma de posesión del nuevo Gobierno", "Cesa inmediatamente y le sustituye el Presidente del Congreso hasta el nuevo nombramiento"]'::jsonb,2,'Art. 101.2 CE','Así lo dispone el art. 101.2 CE.',null),
('admin-navarra:6-d6a369773c','admin-navarra',6,'¿Qué órgano es competente para exigir la responsabilidad criminal del Presidente y los demás miembros del Gobierno?','["El Congreso de los Diputados", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional"]'::jsonb,2,'Art. 102.1 CE','Así lo dispone el art. 102.1 CE.',null),
('admin-navarra:6-87e577ef71','admin-navarra',6,'Si la acusación contra miembros del Gobierno fuera por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, solo podrá plantearse:','["Por iniciativa de la décima parte de los miembros del Congreso y con la aprobación de la mayoría simple de la Cámara en votación pública", "Por iniciativa de la cuarta parte de los miembros del Congreso y con la aprobación de la mayoría absoluta del mismo", "Por iniciativa del Ministerio Fiscal y con la autorización del Senado", "Por iniciativa de la quinta parte de cada Cámara y con aprobación por tres quintos"]'::jsonb,1,'Art. 102.2 CE','La prerrogativa real de gracia no es aplicable a estos supuestos (art. 102.3).',null),
('admin-navarra:6-edc7ed9a49','admin-navarra',6,'Según el art. 103.1 CE, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:','["Eficacia, jerarquía, centralización, concentración y coordinación", "Eficiencia, autonomía, descentralización, desconcentración y cooperación", "Eficacia, jerarquía, descentralización, oportunidad y coordinación", "Eficacia, jerarquía, descentralización, desconcentración y coordinación"]'::jsonb,3,'Art. 103.1 CE','Con sometimiento pleno a la ley y al Derecho.',null),
('admin-navarra:6-ca05d3a07e','admin-navarra',6,'El supremo órgano consultivo del Gobierno es:','["El Consejo de Ministros", "El Consejo Económico y Social", "La Abogacía General del Estado", "El Consejo de Estado"]'::jsonb,3,'Art. 107 CE','Una ley orgánica regula su composición y competencia (LO 3/1980).',null),
('admin-navarra:6-93d246b51d','admin-navarra',6,'Según el art. 106.1 CE, ¿quién controla la potestad reglamentaria y la legalidad de la actuación administrativa?','["El Consejo de Estado", "El Defensor del Pueblo", "Los Tribunales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 106.1 CE','También el sometimiento de la actuación administrativa a los fines que la justifican.',null),
('admin-navarra:6-f36ee0bf32','admin-navarra',6,'Según el art. 105 CE, la ley regulará:','["La responsabilidad penal de los funcionarios públicos", "La audiencia de los ciudadanos en la elaboración de las disposiciones administrativas, el acceso a los archivos y registros administrativos y el procedimiento de producción de los actos administrativos", "El régimen de los partidos políticos y de los sindicatos", "El estatuto de los miembros del Gobierno"]'::jsonb,1,'Art. 105 CE','Garantizando, cuando proceda, la audiencia del interesado.',null),
('admin-navarra:6-67581fa048','admin-navarra',6,'Según el art. 106.2 CE, los particulares tienen derecho a ser indemnizados por toda lesión que sufran en sus bienes y derechos:','["Solo si la lesión se debe a un funcionamiento anormal de los servicios públicos, y siempre que no concurra fuerza mayor", "Salvo que la lesión se produzca en estado de alarma, excepción o sitio", "Siempre que la lesión se deba a dolo o culpa grave de un funcionario", "Siempre que sea consecuencia del funcionamiento de los servicios públicos, salvo fuerza mayor"]'::jsonb,3,'Art. 106.2 CE','En los términos establecidos por la ley.',null),
('admin-navarra:6-8ec6c0dd21','admin-navarra',6,'El Gobierno responde solidariamente de su gestión política:','["Ante el Congreso de los Diputados", "Ante el Rey", "Ante el Senado", "Ante las Cortes Generales en sesión conjunta"]'::jsonb,0,'Art. 108 CE','Así lo dispone el art. 108 CE.',null),
('admin-navarra:6-1630490300','admin-navarra',6,'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:','["Provincias, Comunidades Autónomas y Ciudades Autónomas", "Municipios, islas y Comunidades Autónomas", "Municipios, provincias y Comunidades Autónomas", "Municipios, comarcas, provincias y regiones"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',null),
('admin-navarra:6-f8aa402a47','admin-navarra',6,'Según la Constitución, el gobierno y la administración de los municipios corresponde a:','["Las Diputaciones Provinciales, a través de sus delegaciones comarcales en cada municipio", "Los Delegados del Gobierno, con la colaboración de los Concejales elegidos por los vecinos", "Las asambleas vecinales abiertas, presididas por el Alcalde y el Secretario municipal", "Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales"]'::jsonb,3,'Art. 140 CE','Los Concejales son elegidos por los vecinos por sufragio universal, igual, libre, directo y secreto.',null),
('admin-navarra:6-e6bad9c8ee','admin-navarra',6,'Según el artículo 140 de la Constitución, los Alcaldes serán elegidos:','["Por el Delegado del Gobierno, a propuesta de los Concejales", "Por el Pleno de la Diputación Provincial", "Por los Concejales o por los vecinos", "Siempre por sufragio universal directo de los vecinos"]'::jsonb,2,'Art. 140 CE','La ley regula las condiciones en las que procede el régimen del concejo abierto.',null),
('admin-navarra:6-22394a78cf','admin-navarra',6,'¿Qué tipo de ley es necesaria para alterar los límites provinciales?','["Una ley orgánica aprobada por las Cortes Generales", "Un real decreto del Consejo de Ministros", "Una ley ordinaria de las Cortes Generales, por mayoría absoluta", "Una ley de la Comunidad Autónoma afectada, previo informe estatal"]'::jsonb,0,'Art. 141.1 CE','La provincia es una entidad local con personalidad jurídica propia, agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('admin-navarra:6-3b99450a25','admin-navarra',6,'En los archipiélagos, las islas tendrán además su administración propia en forma de:','["Diputaciones forales", "Cabildos o Consejos", "Juntas Generales", "Mancomunidades insulares"]'::jsonb,1,'Art. 141.4 CE','Los Cabildos existen en Canarias y los Consejos Insulares en Baleares.',null),
('admin-navarra:6-21e222f77b','admin-navarra',6,'Según el artículo 143.2 de la Constitución, la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a:','["Los municipios que representen un tercio del censo electoral de la región histórica", "Las tres cuartas partes de los municipios que representen la mayoría absoluta de los electores", "La mitad de los municipios de cada provincia, sea cual sea su población", "Las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de cada provincia o isla"]'::jsonb,3,'Art. 143.2 CE','Los requisitos deben cumplirse en el plazo de seis meses desde el primer acuerdo de una Corporación local.',null),
('admin-navarra:6-1851ea080d','admin-navarra',6,'¿En qué plazo deben cumplirse los requisitos de iniciativa autonómica del artículo 143.2 de la Constitución?','["Dos años desde que se constituya la asamblea de parlamentarios", "Seis meses desde el primer acuerdo adoptado por alguna de las Corporaciones locales interesadas", "Tres meses desde el acuerdo de la última de las Diputaciones interesadas", "Un año desde la publicación de la Constitución en el Boletín Oficial del Estado y en los diarios oficiales"]'::jsonb,1,'Art. 143.2 CE','Si la iniciativa no prospera, solo puede reiterarse pasados cinco años.',null),
('admin-navarra:6-a908255377','admin-navarra',6,'Si la iniciativa autonómica del artículo 143 no prospera:','["Podrá reiterarse pasados tres años", "Solo podrá reiterarse pasados cinco años", "Podrá reiterarse al año siguiente", "No podrá volver a plantearse nunca"]'::jsonb,1,'Art. 143.3 CE','Así lo dispone el artículo 143.3 de la Constitución.',null),
('admin-navarra:6-9def19ec66','admin-navarra',6,'Según el artículo 144 de la Constitución, las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, podrán:','["Integrar dos Comunidades Autónomas limítrofes en una sola, sin necesidad de referéndum", "Disolver una Comunidad Autónoma que incumpla de forma grave las obligaciones que le imponen la Constitución u otras leyes", "Suspender la autonomía de una Comunidad Autónoma por un plazo máximo de seis meses", "Autorizar la constitución de una Comunidad Autónoma cuyo ámbito territorial no supere el de una provincia y no reúna las condiciones del artículo 143.1"]'::jsonb,3,'Art. 144 a) CE','El artículo 155 no permite disolver Comunidades, sino adoptar medidas para obligarlas a cumplir.',null),
('admin-navarra:6-93d9948cc5','admin-navarra',6,'¿Qué prohíbe el artículo 145 de la Constitución?','["Que una Comunidad Autónoma tenga varias provincias", "La federación de Comunidades Autónomas", "Los convenios entre Comunidades Autónomas", "Que las Comunidades Autónomas tengan himno propio"]'::jsonb,1,'Art. 145.1 CE','Sí se permiten convenios entre Comunidades para la gestión de servicios propios, que deben comunicarse a las Cortes Generales.',null),
('admin-navarra:6-704e433c16','admin-navarra',6,'Los acuerdos de cooperación entre Comunidades Autónomas, distintos de los convenios para gestión de servicios propios, requieren:','["El dictamen del Consejo de Estado", "La aprobación del Consejo de Ministros", "La autorización de las Cortes Generales", "Una simple comunicación a las Cortes Generales"]'::jsonb,2,'Art. 145.2 CE','Los convenios para la gestión y prestación de servicios propios solo deben comunicarse a las Cortes.',null),
('admin-navarra:6-67e322a1f3','admin-navarra',6,'Según el artículo 147 de la Constitución, el Estatuto de Autonomía es:','["Un tratado entre el Estado y la Comunidad Autónoma", "Un reglamento del Gobierno de la Nación para cada Comunidad", "La norma institucional básica de cada Comunidad Autónoma", "Una ley ordinaria aprobada por el Parlamento autonómico"]'::jsonb,2,'Art. 147.1 CE','El Estado lo reconoce y ampara como parte integrante de su ordenamiento jurídico.',null),
('admin-navarra:6-a08b834528','admin-navarra',6,'¿Cuál de los siguientes contenidos NO exige la Constitución que figure en los Estatutos de Autonomía?','["La delimitación de su territorio", "La denominación de la Comunidad", "La lengua cooficial de la Comunidad", "Las competencias asumidas"]'::jsonb,2,'Art. 147.2 CE','El art. 147.2 exige denominación, delimitación del territorio, denominación, organización y sede de las instituciones propias y competencias asumidas.',null),
('admin-navarra:6-c4e3bf3e86','admin-navarra',6,'La reforma de los Estatutos de Autonomía requiere, en todo caso:','["Un referéndum en todo el territorio nacional", "La aprobación por las Cortes Generales mediante ley orgánica", "El acuerdo del Senado por mayoría de tres quintos", "La aprobación por el Gobierno de la Nación mediante real decreto"]'::jsonb,1,'Art. 147.3 CE','El procedimiento lo fija cada Estatuto.',null),
('admin-navarra:6-1a71fd7a61','admin-navarra',6,'Según el artículo 148.2 de la Constitución, las Comunidades Autónomas podían ampliar sucesivamente sus competencias transcurridos:','["Diez años", "Dos años", "Tres años", "Cinco años"]'::jsonb,3,'Art. 148.2 CE','Mediante la reforma de sus Estatutos, dentro del marco del artículo 149.',null),
('admin-navarra:6-cc6904198a','admin-navarra',6,'Las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las Comunidades Autónomas:','["Por acuerdo de la Conferencia de Presidentes", "Solo mediante ley de transferencia", "En virtud de sus respectivos Estatutos", "Siempre, de forma automática"]'::jsonb,2,'Art. 149.3 CE','Las no asumidas por los Estatutos corresponden al Estado, cuyo derecho es en todo caso supletorio del de las Comunidades Autónomas.',null),
('admin-navarra:6-b7e3359e92','admin-navarra',6,'En caso de conflicto, las normas del Estado prevalecen sobre las de las Comunidades Autónomas:','["En todo lo que no esté atribuido a la exclusiva competencia de estas", "Solo en materia de relaciones internacionales", "Solo si la norma estatal es posterior", "En todo caso, sin excepción alguna"]'::jsonb,0,'Art. 149.3 CE','Es la cláusula de prevalencia del derecho estatal.',null),
('admin-navarra:6-17bbabd4c6','admin-navarra',6,'¿Qué leyes permiten a las Cortes atribuir a las Comunidades Autónomas la facultad de dictar normas legislativas en el marco de principios, bases y directrices fijados por una ley estatal?','["Las leyes de bases", "Las leyes marco", "Las leyes de armonización", "Las leyes orgánicas de transferencia"]'::jsonb,1,'Art. 150.1 CE','Las leyes de bases sirven para delegar en el Gobierno la elaboración de textos articulados.',null),
('admin-navarra:6-5838d4b325','admin-navarra',6,'La transferencia o delegación a las Comunidades Autónomas de facultades de titularidad estatal se hace mediante:','["Ley ordinaria", "Real decreto legislativo", "Ley orgánica", "Ley marco"]'::jsonb,2,'Art. 150.2 CE','Debe prever la correspondiente transferencia de medios financieros y las formas de control que se reserve el Estado.',null),
('admin-navarra:6-1b473a9ec4','admin-navarra',6,'¿Quién aprecia la necesidad de dictar una ley de armonización?','["El Senado, por mayoría de dos tercios, a propuesta de la Comisión General de las CCAA", "El Tribunal Constitucional, a instancia del Gobierno o de cincuenta diputados", "Las Cortes Generales, por mayoría absoluta de cada Cámara", "El Gobierno de la Nación, previo dictamen favorable del Consejo de Estado"]'::jsonb,2,'Art. 150.3 CE','Lo exige el interés general, aunque se trate de materias atribuidas a la competencia de las Comunidades Autónomas.',null),
('admin-navarra:6-fc31d03b65','admin-navarra',6,'En la vía del artículo 151 de la Constitución, la iniciativa autonómica debía ratificarse mediante referéndum por:','["La mayoría absoluta de los votos válidos emitidos en el conjunto de toda España", "El voto afirmativo de la mayoría absoluta de los electores de cada provincia", "La mayoría simple de los votos emitidos en el conjunto del territorio de la futura Comunidad", "Dos tercios de los votantes de cada provincia"]'::jsonb,1,'Art. 151.1 CE','Además, la iniciativa debía acordarse por las Diputaciones y por las tres cuartas partes de los municipios de cada provincia.',null),
('admin-navarra:6-9b0beb40eb','admin-navarra',6,'Según el artículo 152 de la Constitución, el Presidente de la Comunidad Autónoma es:','["Elegido por el Senado entre los senadores de la Comunidad", "Elegido directamente por los ciudadanos de la Comunidad en las elecciones autonómicas y nombrado por el Rey", "Nombrado por el Presidente del Gobierno, a propuesta de la Asamblea", "Elegido por la Asamblea Legislativa de entre sus miembros y nombrado por el Rey"]'::jsonb,3,'Art. 152.1 CE','Dirige el Consejo de Gobierno y ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('admin-navarra:6-bbf6a72ff4','admin-navarra',6,'El control económico y presupuestario de los órganos de las Comunidades Autónomas corresponde, según el artículo 153 de la Constitución, a:','["La jurisdicción contencioso-administrativa", "El Tribunal de Cuentas", "El Ministerio de Hacienda", "El Tribunal Constitucional"]'::jsonb,1,'Art. 153 d) CE','El TC controla las disposiciones con fuerza de ley y la jurisdicción contencioso-administrativa, la administración autónoma y sus reglamentos.',null),
('admin-navarra:6-4b6641c451','admin-navarra',6,'¿Quién controla las funciones delegadas a las Comunidades Autónomas conforme al artículo 150.2 de la Constitución?','["El Tribunal de Cuentas, previo informe de la Intervención General", "El Tribunal Constitucional, previo recurso del Senado", "Los Tribunales Superiores de Justicia", "El Gobierno, previo dictamen del Consejo de Estado"]'::jsonb,3,'Art. 153 b) CE','Es una de las cuatro vías de control de la actividad autonómica que enumera el artículo 153.',null),
('admin-navarra:6-f44b9564f5','admin-navarra',6,'Para aplicar las medidas del artículo 155 de la Constitución, el Gobierno necesita:','["Requerir previamente al Presidente de la Comunidad Autónoma y la aprobación de la mayoría absoluta del Senado", "La aprobación del Consejo de Estado y del Congreso", "La autorización del Congreso de los Diputados por mayoría de tres quintos", "Un dictamen favorable del Tribunal Constitucional"]'::jsonb,0,'Art. 155.1 CE','Se aplica si una Comunidad no cumple las obligaciones de la Constitución o las leyes o actúa contra el interés general de España.',null),
('admin-navarra:6-cf05c48fc5','admin-navarra',6,'¿Qué fondo prevé el artículo 158.2 de la Constitución para corregir desequilibrios económicos interterritoriales?','["El Fondo de Suficiencia Global", "El Fondo de Compensación", "El Fondo de Garantía de Servicios Públicos Fundamentales", "El Fondo de Cohesión Territorial"]'::jsonb,1,'Art. 158.2 CE','Sus recursos se distribuyen por las Cortes Generales entre las Comunidades Autónomas y provincias.',null),
('admin-navarra:6-2033c7b537','admin-navarra',6,'Según el artículo 134 de la Constitución, la elaboración de los Presupuestos Generales del Estado corresponde:','["A las Cortes Generales", "Al Ministerio de Hacienda y al Banco de España", "Al Congreso de los Diputados", "Al Gobierno"]'::jsonb,3,'Art. 134.1 CE','Al Gobierno le corresponde elaborarlos y a las Cortes Generales examinarlos, enmendarlos y aprobarlos.',null),
('admin-navarra:6-6683bdb6bd','admin-navarra',6,'Según la Constitución, el Gobierno debe presentar los Presupuestos Generales del Estado ante el Congreso:','["Al menos tres meses antes de la expiración de los del año anterior", "Antes del 31 de diciembre del año anterior", "En el primer mes de cada período de sesiones", "Al menos seis meses antes de la expiración de los del año anterior, junto con su memoria"]'::jsonb,0,'Art. 134.3 CE','La Ley General Presupuestaria concreta que debe remitirse antes del 1 de octubre.',null),
('admin-navarra:6-c9323cf0ed','admin-navarra',6,'Si la Ley de Presupuestos no se aprueba antes del primer día del ejercicio económico correspondiente:','["Se consideran automáticamente prorrogados los presupuestos del ejercicio anterior hasta la aprobación de los nuevos", "Se aplican los presupuestos que presentó el Gobierno, a la espera de su aprobación", "El Gobierno puede aprobarlos mediante real decreto-ley con la convalidación posterior del Congreso", "No puede realizarse ningún gasto público hasta su aprobación definitiva"]'::jsonb,0,'Art. 134.4 CE y art. 38 Ley 47/2003','La prórroga no afecta a los créditos de programas que terminen en el ejercicio anterior.',null),
('admin-navarra:6-a73124503f','admin-navarra',6,'Según el artículo 134 de la Constitución, los Presupuestos Generales del Estado tienen carácter:','["Bienal", "Anual", "Plurianual", "Cuatrienal"]'::jsonb,1,'Art. 134.2 CE','Incluyen la totalidad de los gastos e ingresos del sector público estatal y el importe de los beneficios fiscales que afecten a los tributos del Estado.',null),
('admin-navarra:6-bea8d49a1a','admin-navarra',6,'¿Puede la Ley de Presupuestos crear tributos?','["Sí, siempre que se trate de tasas o precios públicos", "No, ni tampoco modificarlos en ningún caso, ni siquiera cuando lo prevea una ley tributaria", "Sí, porque es la ley que aprueba los ingresos del Estado", "No, aunque puede modificarlos si una ley tributaria sustantiva así lo prevé"]'::jsonb,3,'Art. 134.7 CE','Es una limitación constitucional al contenido de la Ley de Presupuestos.',null),
('admin-navarra:6-c9cc0a6a21','admin-navarra',6,'Toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos presupuestarios requiere para su tramitación:','["La mayoría absoluta del Congreso", "El dictamen del Consejo de Estado", "El informe del Tribunal de Cuentas", "La conformidad del Gobierno"]'::jsonb,3,'Art. 134.6 CE','Es una garantía del equilibrio presupuestario aprobado.',null),
('admin-navarra:6-b95a939339','admin-navarra',6,'¿Qué órgano es el supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público?','["El Tribunal Constitucional", "El Tribunal de Cuentas", "La Autoridad Independiente de Responsabilidad Fiscal", "La Intervención General de la Administración del Estado"]'::jsonb,1,'Art. 136.1 CE','Depende directamente de las Cortes Generales. La IGAE ejerce el control interno.',null),
('admin-navarra:6-5b443c9676','admin-navarra',6,'¿Qué artículo de la Constitución consagra el principio de estabilidad presupuestaria tras la reforma de 2011?','["El artículo 136", "El artículo 134", "El artículo 135", "El artículo 131"]'::jsonb,2,'Art. 135 CE','Todas las Administraciones Públicas adecuarán sus actuaciones al principio de estabilidad presupuestaria.',null),
('admin-navarra:6-65e71180db','admin-navarra',6,'¿A quién se remite la Cuenta General del Estado para su fiscalización?','["Al Tribunal de Cuentas", "A la Comisión Europea", "Al Banco de España", "Al Consejo de Ministros"]'::jsonb,0,'Art. 136 CE','El Tribunal de Cuentas remite a las Cortes un informe anual sobre ella.',null),
('admin-navarra:6-190ca948d7','admin-navarra',6,'La reforma del artículo 49 de la Constitución aprobada en 2024 sustituyó la expresión «disminuidos físicos, sensoriales y psíquicos» por:','["Personas con discapacidad", "Personas dependientes", "Personas con capacidades diferentes", "Personas con diversidad funcional"]'::jsonb,0,'Art. 49 CE (reforma de 17 de febrero de 2024)','Fue la tercera reforma de la Constitución, tras las de 1992 (art. 13.2) y 2011 (art. 135).',null),
('admin-navarra:7-e7fbb4386d','admin-navarra',7,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('admin-navarra:7-59c431d0a2','admin-navarra',7,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('admin-navarra:7-bc9d22c222','admin-navarra',7,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('admin-navarra:7-deb7b146e1','admin-navarra',7,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('admin-navarra:7-37ad08524c','admin-navarra',7,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('admin-navarra:7-68d78cde21','admin-navarra',7,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('admin-navarra:7-98e4aa14c6','admin-navarra',7,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('admin-navarra:7-468baa9c03','admin-navarra',7,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null),
('admin-navarra:7-52548d492f','admin-navarra',7,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('admin-navarra:7-6771348924','admin-navarra',7,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('admin-navarra:7-a8cb2039d1','admin-navarra',7,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('admin-navarra:7-3f72583cd1','admin-navarra',7,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('admin-navarra:7-88338893d6','admin-navarra',7,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('admin-navarra:7-6f7a20f6e6','admin-navarra',7,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('admin-navarra:7-4733847833','admin-navarra',7,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('admin-navarra:7-69617aea8c','admin-navarra',7,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('admin-navarra:7-f099b5ac6c','admin-navarra',7,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null),
('admin-navarra:7-5eb872a4f6','admin-navarra',7,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('admin-navarra:7-13fa14b699','admin-navarra',7,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('admin-navarra:7-31c2aa11b8','admin-navarra',7,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null),
('admin-navarra:7-1bad8ddd87','admin-navarra',7,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('admin-navarra:7-e2e9f914bb','admin-navarra',7,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('admin-navarra:8-639ed61ab7','admin-navarra',8,'Según la LORAFNA, ¿cómo se define Navarra?','["Como una comunidad autónoma de régimen común, con competencias forales asumidas por la vía del artículo 143 de la Constitución", "Como una Comunidad Foral con régimen, autonomía e instituciones propias, indivisible, integrada en la Nación española", "Como una provincia foral con autonomía administrativa", "Como un territorio histórico con instituciones de régimen especial dentro del País Vasco"]'::jsonb,1,'Art. 1 LORAFNA','El art. 1 dice que Navarra constituye una Comunidad Foral con régimen, autonomía e instituciones propias, indivisible, integrada en la Nación española y solidaria con todos sus pueblos.',null),
('admin-navarra:8-16f320010f','admin-navarra',8,'¿Con arreglo a qué leyes históricas se respetan los derechos originarios de Navarra según la LORAFNA?','["La Ley de 25 de octubre de 1839 y la Ley Paccionada de 16 de agosto de 1841", "La Constitución de Cádiz y el Fuero General de Navarra", "La Ley de 1876 y el Convenio Económico de 1969", "El Real Decreto-ley Paccionado de 1925 y la Ley de 21 de julio de 1876, de abolición foral"]'::jsonb,0,'Art. 2 LORAFNA','Se respetan con arreglo a la Ley de 25 de octubre de 1839, la Ley Paccionada de 16 de agosto de 1841, la propia LORAFNA y la Constitución.',null),
('admin-navarra:8-cac8caf03c','admin-navarra',8,'¿Qué merindades históricas integran el territorio de Navarra según la LORAFNA?','["Pamplona, Baztán, Tudela, Sangüesa y Estella", "Pamplona, Estella, Tudela, Tafalla y Olite", "Pamplona, Estella, Tudela, Sangüesa y Tafalla", "Pamplona, Estella, Tudela, Sangüesa y Olite"]'::jsonb,3,'Art. 4 LORAFNA','El territorio está integrado por los municipios de las merindades históricas de Pamplona, Estella, Tudela, Sangüesa y Olite.',null),
('admin-navarra:8-13b5050082','admin-navarra',8,'¿Quiénes tienen la condición política de navarros según la LORAFNA?','["Los que tengan la condición civil foral de navarro", "Los españoles con vecindad administrativa en cualquier municipio de Navarra", "Los nacidos en Navarra, residan donde residan", "Los residentes en Navarra durante al menos cinco años, tengan o no la nacionalidad española"]'::jsonb,1,'Art. 5 LORAFNA','Tienen la condición política de navarros los españoles con vecindad administrativa en cualquier municipio de Navarra.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:8-40a3fe0fa6','admin-navarra',8,'¿Cómo es la bandera de Navarra según la LORAFNA?','["Roja, con las cadenas de oro sin corona", "Roja y amarilla, con el escudo en el centro", "Roja, con el escudo en el centro", "Blanca, con el escudo en el ángulo superior"]'::jsonb,2,'Art. 7 LORAFNA','La bandera de Navarra es de color rojo, con el escudo en el centro.',null),
('admin-navarra:8-605f21f2f4','admin-navarra',8,'¿Qué carácter tiene el vascuence según la LORAFNA?','["Lengua cooficial en todo el territorio de Navarra", "Lengua oficial en las zonas vascoparlantes de Navarra", "Lengua oficial solo en la enseñanza", "Lengua propia sin carácter oficial"]'::jsonb,1,'Art. 9 LORAFNA','El castellano es la lengua oficial de Navarra; el vascuence tiene también carácter oficial en las zonas vascoparlantes, que determina una ley foral.',null),
('admin-navarra:8-c1e667f594','admin-navarra',8,'¿Cuáles son las instituciones forales de Navarra según la LORAFNA?','["El Parlamento, el Gobierno o Diputación Foral y el Presidente de la Comunidad Foral", "El Parlamento, el Consejo de Navarra y el Tribunal Superior de Justicia", "El Parlamento, el Gobierno, la Cámara de Comptos y el Defensor del Pueblo de Navarra", "La Diputación Foral, los ayuntamientos y los concejos"]'::jsonb,0,'Art. 10 LORAFNA','Las instituciones forales son el Parlamento o Cortes de Navarra, el Gobierno de Navarra o Diputación Foral y el Presidente de la Comunidad Foral.',null),
('admin-navarra:8-88a3751664','admin-navarra',8,'¿Qué corresponde a Navarra según el art. 39.1 de la LORAFNA?','["Las mismas competencias que las comunidades autónomas del art. 143 de la Constitución, ampliables por ley orgánica de transferencia", "Todas las competencias no reservadas a la Unión Europea", "Solo las competencias que le transfiera el Estado por ley orgánica", "Las competencias que ejerce al amparo de la Ley Paccionada, las que le integra la LORAFNA y las que el Estado atribuya con carácter general a las comunidades o provincias"]'::jsonb,3,'Art. 39 LORAFNA','Corresponden a Navarra las competencias de la Ley Paccionada, las que le integra la LORAFNA y las que la legislación del Estado atribuya, transfiera o delegue con carácter general.',null),
('admin-navarra:8-3d08a6e4a4','admin-navarra',8,'¿Qué potestades corresponden a Navarra en las materias de su competencia exclusiva?','["De desarrollo legislativo y de ejecución de las bases estatales, con la inspección correspondiente", "Solo reglamentaria y administrativa", "Legislativa, reglamentaria, administrativa con la inspección y revisora en vía administrativa", "Legislativa y judicial"]'::jsonb,2,'Art. 40 LORAFNA','En las materias de competencia exclusiva corresponden las potestades legislativa, reglamentaria, administrativa (incluida la inspección) y revisora en vía administrativa.',null),
('admin-navarra:8-dfd5df56a4','admin-navarra',8,'En las materias de competencia exclusiva de Navarra, ¿qué derecho se aplica en defecto de derecho propio?','["Ninguno, debe dictarse norma foral", "El de la Unión Europea", "El de la comunidad autónoma limítrofe", "El del Estado, de forma supletoria"]'::jsonb,3,'Art. 40 LORAFNA','El derecho navarro se aplica con preferencia; en defecto de derecho propio se aplica supletoriamente el derecho del Estado.',null),
('admin-navarra:8-993fcdce97','admin-navarra',8,'¿Cuál de estas materias es de competencia exclusiva de Navarra según el art. 44 de la LORAFNA?','["Ordenación del territorio, urbanismo y vivienda", "Régimen penitenciario", "Legislación laboral", "Propiedad intelectual e industrial"]'::jsonb,0,'Art. 44 LORAFNA','El art. 44 incluye, entre otras, la ordenación del territorio, urbanismo y vivienda; la laboral, penitenciaria y propiedad intelectual son de ejecución (art. 58).',null),
('admin-navarra:8-b5e0495623','admin-navarra',8,'¿Por qué sistema se regula la actividad tributaria y financiera de Navarra?','["Por la Ley Orgánica de Financiación de las Comunidades Autónomas", "Por el sistema tradicional del Convenio Económico", "Por el Concierto Económico con el País Vasco", "Por el sistema de financiación común de las comunidades autónomas"]'::jsonb,1,'Art. 45 LORAFNA','La actividad tributaria y financiera de Navarra se regula por el sistema tradicional del Convenio Económico.',null),
('admin-navarra:8-43df411f49','admin-navarra',8,'¿Cómo se aprueban los Convenios Económicos entre Navarra y el Estado?','["Por ley orgánica de las Cortes Generales", "Por ley foral aprobada por mayoría absoluta", "Por el Parlamento Foral y las Cortes Generales mediante ley ordinaria", "Por real decreto del Gobierno de la Nación, previo acuerdo con la Diputación Foral"]'::jsonb,2,'Art. 45 LORAFNA','Una vez suscritos, se someten al Parlamento Foral y a las Cortes Generales para su aprobación mediante ley ordinaria.',null),
('admin-navarra:8-7809e6e61a','admin-navarra',8,'¿Qué autonomía tienen los municipios de Navarra según la LORAFNA?','["Plena autonomía legislativa", "La que les reconozca cada año la Ley Foral de Presupuestos Generales de Navarra", "Solo la que determine la Diputación Foral", "Como mínimo, la que con carácter general se reconozca a los demás municipios de la Nación"]'::jsonb,3,'Art. 46 LORAFNA','Los municipios de Navarra gozarán, como mínimo, de la autonomía que con carácter general se reconozca a los demás municipios.',null),
('admin-navarra:8-fe81632713','admin-navarra',8,'¿Bajo qué mando supremo actúa la Policía Foral según la LORAFNA?','["El de la Junta de Seguridad", "El del Delegado del Gobierno en Navarra", "El de la Diputación Foral", "El del Ministerio del Interior"]'::jsonb,2,'Art. 51 LORAFNA','La Policía Foral, bajo el mando supremo de la Diputación Foral, continúa ejerciendo sus funciones.',null),
('admin-navarra:8-111bb4cabf','admin-navarra',8,'¿Qué órgano coordina la Policía Foral y las Fuerzas y Cuerpos de Seguridad del Estado?','["Una Junta de Seguridad con igual número de representantes de la Diputación y del Gobierno de la Nación", "La Junta de Cooperación entre la Administración del Estado y la Diputación Foral", "La Comisión Mixta de Transferencias", "El Consejo de Navarra"]'::jsonb,0,'Art. 51 LORAFNA','Se establecerá, en su caso, una Junta de Seguridad formada por un número igual de representantes de la Diputación Foral y del Gobierno de la Nación.',null),
('admin-navarra:8-c6b1806a9e','admin-navarra',8,'¿Qué corresponde a Navarra en materia de legislación laboral según la LORAFNA?','["El desarrollo legislativo de las bases", "La ejecución de la legislación del Estado", "Ninguna competencia", "La competencia legislativa exclusiva"]'::jsonb,1,'Art. 58 LORAFNA','Corresponde a Navarra la ejecución de la legislación del Estado en materia laboral, sin perjuicio de la alta inspección estatal.',null),
('admin-navarra:8-0ed6f6f3d4','admin-navarra',8,'¿Qué órgano resuelve las discrepancias entre el Estado y Navarra sobre la aplicación de la LORAFNA?','["El Consejo de Navarra", "La Junta de Seguridad", "El Tribunal Superior de Justicia de Navarra", "La Junta de Cooperación"]'::jsonb,3,'Art. 69 LORAFNA','Las discrepancias se plantean y, en su caso, resuelven en una Junta de Cooperación con igual número de representantes de ambas partes.',null),
('admin-navarra:8-8579f9e1c2','admin-navarra',8,'¿En qué plazo entran en vigor los convenios de Navarra con comunidades limítrofes para servicios propios?','["Al día siguiente de su publicación en el BON", "Tras su aprobación por las Cortes Generales", "A los veinte días de su comunicación a las Cortes Generales", "A los treinta días de su comunicación a las Cortes Generales"]'::jsonb,2,'Art. 70 LORAFNA','Los convenios con el País Vasco y comunidades limítrofes entran en vigor a los veinte días de su comunicación a las Cortes; con las demás, a los treinta.',null),
('admin-navarra:8-d31d9b89d4','admin-navarra',8,'¿Puede modificarse unilateralmente el Amejoramiento del Fuero?','["Sí, mediante referéndum en Navarra", "No, es inmodificable unilateralmente", "Sí, por ley orgánica de las Cortes Generales", "Sí, por ley foral aprobada por mayoría absoluta"]'::jsonb,1,'Art. 71 LORAFNA','Dada la naturaleza del régimen foral, el Amejoramiento es inmodificable unilateralmente.',null),
('admin-navarra:8-18c45829d0','admin-navarra',8,'¿A quién corresponde la iniciativa de reforma de la LORAFNA?','["A la Diputación Foral o al Gobierno de la Nación", "Solo al Parlamento de Navarra", "A los ayuntamientos que representen un tercio de la población", "A las Cortes Generales o al Parlamento de Navarra"]'::jsonb,0,'Art. 71 LORAFNA','La iniciativa corresponde a la Diputación Foral o al Gobierno de la Nación; tras negociar, formulan de común acuerdo la propuesta.',null),
('admin-navarra:9-6fa44d0548','admin-navarra',9,'Según la Ley Foral 19/1984, ¿qué es la Cámara de Comptos de Navarra?','["El órgano técnico dependiente del Parlamento, fiscalizador de la gestión económica y financiera del sector público foral", "El órgano consultivo superior del Gobierno en materia económica", "El órgano de control interno del Gobierno de Navarra, adscrito a Hacienda", "El tribunal que enjuicia en exclusiva la responsabilidad contable en Navarra"]'::jsonb,0,'Art. 1 LF 19/1984 Navarra','Es el órgano técnico dependiente del Parlamento, fiscalizador de la gestión económica y financiera del sector público de la Comunidad Foral y de los fondos públicos.',null),
('admin-navarra:9-706e8420fb','admin-navarra',9,'¿Cuáles son las funciones propias de la Cámara de Comptos según la Ley Foral 19/1984?','["Recaudar los tributos propios y gestionar la tesorería foral", "Controlar las cuentas y la gestión económica del sector público de Navarra y asesorar al Parlamento", "Elaborar los Presupuestos Generales de Navarra y la Cuenta General", "Ejercer la función interventora previa de los gastos del Gobierno"]'::jsonb,1,'Art. 4 LF 19/1984 Navarra','Sus funciones propias son controlar las cuentas y la gestión económica del sector público y asesorar al Parlamento en materias económico-financieras.',null),
('admin-navarra:9-6c322985ad','admin-navarra',9,'¿Antes de qué fecha remite la Cámara de Comptos a la Mesa del Parlamento la rendición de sus cuentas?','["Antes del 31 de enero de cada año", "Antes del 1 de noviembre de cada año", "Antes del 1 de marzo de cada año", "Antes del 30 de junio de cada año"]'::jsonb,2,'Art. 6 LF 19/1984 Navarra','La Cámara remite a la Mesa del Parlamento antes del día 1 de marzo de cada año la rendición de sus cuentas.',null),
('admin-navarra:9-fb24907cb3','admin-navarra',9,'¿Cuál es la función básica de la Cámara de Comptos según la Ley Foral 19/1984?','["La función de intervención previa", "La función de asesoramiento al Gobierno", "La función jurisdiccional contable", "La función fiscalizadora"]'::jsonb,3,'Art. 8 LF 19/1984 Navarra','La función fiscalizadora es la básica de la Cámara de Comptos.',null),
('admin-navarra:9-c13f1082c1','admin-navarra',9,'¿En qué plazo debe la Cámara de Comptos examinar y censurar las Cuentas Generales de Navarra?','["En los tres meses siguientes a su remisión por el Parlamento", "En los dos meses siguientes a su remisión por el Parlamento", "En los seis meses siguientes al cierre del ejercicio", "En el mes siguiente a su aprobación por el Gobierno"]'::jsonb,0,'Art. 8 LF 19/1984 Navarra','El examen y censura de las Cuentas Generales se efectúa dentro de los tres meses siguientes a su remisión a la Cámara por el Parlamento.',null),
('admin-navarra:9-91d17d2329','admin-navarra',9,'¿Dónde se publican los informes y memorias de la Cámara de Comptos y en qué plazo?','["En el Boletín Oficial de Navarra, en el plazo de un mes", "En la sede electrónica del Gobierno, sin plazo fijo", "En el Boletín Oficial del Parlamento, en el plazo de dos meses", "En el Boletín Oficial del Estado, en el plazo de tres meses"]'::jsonb,2,'Art. 9 LF 19/1984 Navarra','Sus Informes y Memorias se publican en el Boletín Oficial del Parlamento en el plazo de 2 meses.',null),
('admin-navarra:9-80b657ccf4','admin-navarra',9,'¿Qué tiene por objeto el control de eficacia que realiza la Cámara de Comptos?','["Comprobar el reflejo contable de la situación patrimonial", "Determinar el grado en que se han conseguido los objetivos previstos", "Verificar la adecuación de la actividad al ordenamiento jurídico", "Analizar si los objetivos se alcanzaron con el menor coste"]'::jsonb,1,'Art. 9 LF 19/1984 Navarra','El control de eficacia determina el grado de consecución de los objetivos previstos; el de economía o eficiencia, si se alcanzaron con el menor coste.',null),
('admin-navarra:9-e16d9b9b33','admin-navarra',9,'¿Cuáles son los órganos de la Cámara de Comptos según la Ley Foral 19/1984?','["El Presidente, los Consejeros y el Fiscal", "El Presidente, los Letrados y el Gabinete Técnico", "El Pleno, la Comisión de Gobierno y el Presidente", "El Presidente, los Auditores y la Secretaría General"]'::jsonb,3,'Art. 14 LF 19/1984 Navarra','Son órganos de la Cámara el Presidente, los Auditores y la Secretaría General.',null),
('admin-navarra:9-5a4db8c3e7','admin-navarra',9,'¿Quién nombra al Presidente de la Cámara de Comptos y por cuánto tiempo?','["El Pleno del Parlamento de Navarra, por seis años", "El Gobierno de Navarra, por cuatro años", "El Presidente del Parlamento, por cinco años", "El Pleno del Parlamento de Navarra, por cuatro años"]'::jsonb,0,'Art. 25 LF 19/1984 Navarra','Es nombrado mediante elección por el Pleno del Parlamento de Navarra por un período de seis años.',null),
('admin-navarra:9-8eeb7387d4','admin-navarra',9,'¿Qué mayoría se exige en la primera votación para elegir al Presidente de la Cámara de Comptos?','["Mayoría simple", "Mayoría absoluta", "Mayoría de dos tercios", "Mayoría de tres quintos"]'::jsonb,1,'Art. 25 LF 19/1984 Navarra','Se exige mayoría absoluta en la primera votación; si no, hay una segunda votación entre los dos más votados.',null),
('admin-navarra:9-8acf1d81b9','admin-navarra',9,'¿Qué mayoría parlamentaria exige la remoción del Presidente de la Cámara de Comptos por incumplimiento grave de sus deberes?','["Las tres quintas partes del Parlamento", "La mayoría absoluta del Parlamento", "La mayoría simple de la Mesa", "Las dos terceras partes de los miembros del Parlamento"]'::jsonb,3,'Art. 26 LF 19/1984 Navarra','Por incapacidad, incompatibilidad o incumplimiento grave, la remoción exige que lo aprecien las dos terceras partes de los miembros del Parlamento.',null),
('admin-navarra:9-6b5b70b025','admin-navarra',9,'¿Quién sustituye al Presidente de la Cámara de Comptos en caso de ausencia, enfermedad o vacante temporal?','["El Presidente del Parlamento de Navarra", "El Auditor de mayor antigüedad", "El Secretario General de la Cámara", "El Letrado de mayor edad"]'::jsonb,2,'Art. 27 LF 19/1984 Navarra','En esos casos le sustituye en sus funciones el Secretario General de la Cámara.',null),
('admin-navarra:9-08ec93fda3','admin-navarra',9,'¿Quién nombra al Secretario General de la Cámara de Comptos?','["El Pleno del Parlamento, por mayoría absoluta", "El Gobierno de Navarra, a propuesta del Presidente", "El Presidente de la Cámara, libremente, de entre los Letrados", "La Mesa del Parlamento, de entre los Auditores"]'::jsonb,2,'Art. 30 LF 19/1984 Navarra','Es nombrado y cesado libremente por el Presidente de entre los Letrados.',null),
('admin-navarra:9-c1afbba7f6','admin-navarra',9,'¿Con qué antelación mínima notifica la Cámara de Comptos el comienzo de una fiscalización?','["Un mes", "Quince días", "Tres días", "Una semana"]'::jsonb,3,'Art. 21 LF 19/1984 Navarra','Notifica a los responsables de los servicios el comienzo de la fiscalización con una antelación mínima de una semana.',null),
('admin-navarra:9-703232a769','admin-navarra',9,'¿Cómo define la Ley Foral 4/2000 al Defensor del Pueblo de la Comunidad Foral de Navarra?','["Como alto comisionado del Parlamento de Navarra para la defensa de los derechos y libertades", "Como órgano técnico de control externo de la gestión económica del sector público foral", "Como órgano consultivo del Gobierno de Navarra en materia de derechos de la ciudadanía", "Como comisionado del Gobierno de Navarra para la supervisión de las entidades locales"]'::jsonb,0,'Art. 1 LF 4/2000 Navarra','Es el alto comisionado del Parlamento de Navarra, designado por este para la defensa y mejora del nivel de protección de los derechos y libertades.',null),
('admin-navarra:9-d80cbeca8b','admin-navarra',9,'¿Para qué periodo es elegido el Defensor del Pueblo de la Comunidad Foral de Navarra?','["Cinco años", "Seis años", "Cuatro años", "Ocho años"]'::jsonb,1,'Art. 2 LF 4/2000 Navarra','Es elegido por el Parlamento de Navarra para un periodo de seis años.',null),
('admin-navarra:9-622f5bfa0d','admin-navarra',9,'¿Qué mayoría exige la elección del Defensor del Pueblo de Navarra en el Pleno del Parlamento?','["Mayoría simple de los votos emitidos en el Pleno", "Tres quintas partes de los miembros del Parlamento", "Mayoría absoluta de los miembros del Parlamento", "Dos tercios de los miembros del Parlamento"]'::jsonb,1,'Art. 2 LF 4/2000 Navarra','Será designado quien obtenga el voto favorable de las tres quintas partes de los miembros del Parlamento.',null),
('admin-navarra:9-de65b4e0f4','admin-navarra',9,'¿Qué órgano del Parlamento de Navarra propone el candidato a Defensor del Pueblo?','["La Comisión de Presidencia", "La Mesa del Parlamento", "La Comisión de Régimen Foral", "La Junta de Portavoces"]'::jsonb,2,'Art. 2 LF 4/2000 Navarra','La Comisión de Régimen Foral propone al candidato con el voto favorable de las tres quintas partes de sus miembros.',null),
('admin-navarra:9-5eb6f4c30f','admin-navarra',9,'Si no se alcanza la mayoría exigida en el Pleno, ¿en qué plazo máximo se reúne la Comisión de Régimen Foral para formular nueva propuesta?','["Un mes", "Quince días", "Diez días", "Dos meses"]'::jsonb,0,'Art. 2 LF 4/2000 Navarra','La Comisión de Régimen Foral se reunirá en el plazo máximo de un mes para formular nueva propuesta.',null),
('admin-navarra:9-f1266ad117','admin-navarra',9,'¿Ante quién toma posesión de su cargo el Defensor del Pueblo de la Comunidad Foral de Navarra?','["Ante la Comisión de Régimen Foral", "Ante el Presidente del Gobierno de Navarra", "Ante el Pleno del Parlamento", "Ante la Mesa del Parlamento"]'::jsonb,3,'Art. 4 LF 4/2000 Navarra','Toma posesión ante la Mesa del Parlamento, prestando juramento o promesa.',null),
('admin-navarra:9-8987aa00b5','admin-navarra',9,'¿En qué plazo debe el Defensor del Pueblo de Navarra cesar en toda situación de incompatibilidad tras su nombramiento?','["Dentro de los cinco días siguientes a su nombramiento", "Dentro del mes siguiente a su nombramiento", "Dentro de los diez días siguientes a su nombramiento", "Dentro de los quince días siguientes a su toma de posesión"]'::jsonb,2,'Art. 7 LF 4/2000 Navarra','Cesará dentro de los diez días siguientes a su nombramiento y, en todo caso, antes de tomar posesión; si no, se entiende que no acepta.',null),
('admin-navarra:9-55f00ef56e','admin-navarra',9,'¿Quién declara la vacante del Defensor del Pueblo de Navarra en caso de fallecimiento, renuncia o expiración del mandato?','["La Comisión de Régimen Foral", "El Presidente del Parlamento de Navarra", "El Pleno por mayoría de tres quintos", "La Mesa del Parlamento de Navarra"]'::jsonb,1,'Art. 8 LF 4/2000 Navarra','En esos casos la vacante la declara el Presidente del Parlamento; en los demás, el Pleno por tres quintos, con audiencia del interesado.',null),
('admin-navarra:9-e17b7255c9','admin-navarra',9,'¿Quién desempeña interinamente las funciones del Defensor del Pueblo de Navarra en caso de cese o incapacidad temporal?','["El Adjunto al Defensor del Pueblo", "El Presidente del Parlamento", "El presidente de la Comisión de Régimen Foral", "El Defensor del Pueblo designado por las Cortes Generales"]'::jsonb,0,'Art. 8 LF 4/2000 Navarra','En tanto no haya nueva designación, desempeña sus funciones interinamente el Adjunto.',null),
('admin-navarra:9-aa245acb0d','admin-navarra',9,'¿Quién nombra y separa al Adjunto al Defensor del Pueblo de Navarra?','["El Presidente del Parlamento, a propuesta del Defensor", "La Mesa del Parlamento, oída la Junta de Portavoces", "El Pleno del Parlamento, a propuesta del Defensor y por mayoría absoluta", "El propio Defensor, previa conformidad de tres quintos de la Comisión de Régimen Foral"]'::jsonb,3,'Art. 9 LF 4/2000 Navarra','El Defensor nombra y separa a su Adjunto, previa conformidad de las tres quintas partes de los miembros de la Comisión de Régimen Foral.',null),
('admin-navarra:9-254dea92cd','admin-navarra',9,'Según la LORAFNA, ¿cuál de estas funciones corresponde al Parlamento de Navarra?','["Ejercer la función revisora en vía administrativa", "Elaborar los Presupuestos Generales de Navarra", "Aprobar los Presupuestos y las Cuentas de Navarra", "Dictar decretos forales legislativos"]'::jsonb,2,'Art. 11 LORAFNA','El Parlamento representa al pueblo navarro, ejerce la potestad legislativa, aprueba los Presupuestos y las Cuentas e impulsa y controla la acción de la Diputación.',null),
('admin-navarra:9-8bdf0b4885','admin-navarra',9,'¿Quién designa a los senadores que corresponden a Navarra como Comunidad Foral?','["El Presidente de la Comunidad Foral", "El Parlamento de Navarra", "Los ayuntamientos de Navarra", "El Gobierno de Navarra"]'::jsonb,1,'Art. 12 LORAFNA','Compete al Parlamento la designación de los senadores que pudieran corresponder a Navarra como Comunidad Foral.',null),
('admin-navarra:9-7d8607cc06','admin-navarra',9,'¿Qué tribunal decide sobre la inculpación de un parlamentario foral por delitos cometidos en Navarra?','["El Tribunal Superior de Justicia de Navarra", "La Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "La Audiencia Provincial de Navarra"]'::jsonb,0,'Art. 14 LORAFNA','Corresponde decidir sobre su inculpación, prisión, procesamiento y juicio al Tribunal Superior de Justicia de Navarra; fuera de Navarra, al Tribunal Supremo.',null),
('admin-navarra:9-b3435302be','admin-navarra',9,'¿Por cuánto tiempo se elige el Parlamento de Navarra?','["Tres años", "Cinco años", "Seis años", "Cuatro años"]'::jsonb,3,'Art. 15 LORAFNA','El Parlamento se elige por sufragio universal, libre, igual, directo y secreto por un período de cuatro años.',null),
('admin-navarra:9-d8845513bf','admin-navarra',9,'¿Entre cuántos miembros debe tener el Parlamento de Navarra según la LORAFNA?','["Entre cuarenta y cinco y sesenta y cinco", "Entre treinta y cincuenta", "Entre cuarenta y sesenta", "Entre cincuenta y setenta"]'::jsonb,2,'Art. 15 LORAFNA','El número de miembros no será inferior a cuarenta ni superior a sesenta; una ley foral fija el número concreto.',null),
('admin-navarra:9-e339f36fa4','admin-navarra',9,'¿Qué mayoría exige la aprobación o reforma del Reglamento del Parlamento de Navarra?','["Mayoría de tres quintos", "Mayoría de dos tercios", "Mayoría simple", "Mayoría absoluta en una votación final sobre el conjunto"]'::jsonb,3,'Art. 16 LORAFNA','Precisa el voto favorable de la mayoría absoluta de los miembros en una votación final sobre el conjunto del proyecto.',null),
('admin-navarra:9-20d103885a','admin-navarra',9,'¿Quién puede pedir la convocatoria de sesiones extraordinarias del Parlamento de Navarra?','["Cualquier parlamentario", "La Comisión Permanente, una quinta parte de los parlamentarios, los grupos que fije el Reglamento o la Diputación Foral", "Solo el Presidente del Gobierno", "La mayoría absoluta de los parlamentarios forales, exclusivamente a iniciativa propia o del Presidente"]'::jsonb,1,'Art. 17 LORAFNA','Las sesiones extraordinarias se convocan a petición de la Comisión Permanente, una quinta parte de los parlamentarios, los grupos que fije el Reglamento o la Diputación Foral.',null),
('admin-navarra:9-9e919a5cb3','admin-navarra',9,'Según la LORAFNA, ¿qué es la Cámara de Comptos?','["El órgano fiscalizador externo de la gestión económica y financiera del sector público de Navarra", "El órgano de control interno del Gobierno de Navarra", "El órgano consultivo superior de la Comunidad Foral", "El tribunal que enjuicia en Navarra la responsabilidad contable de quienes manejan fondos públicos"]'::jsonb,0,'Art. 18 bis LORAFNA','La Cámara de Comptos es el órgano fiscalizador externo; el enjuiciamiento de la responsabilidad contable corresponde al Tribunal de Cuentas.',null),
('admin-navarra:9-3024ec96d6','admin-navarra',9,'¿De quién depende orgánicamente la Cámara de Comptos?','["Del Gobierno de Navarra", "Del Departamento de Hacienda", "Del Parlamento de Navarra", "Del Tribunal de Cuentas"]'::jsonb,2,'Art. 18 bis LORAFNA','La Cámara de Comptos depende orgánicamente del Parlamento de Navarra.',null),
('admin-navarra:9-4ff6cd3dd4','admin-navarra',9,'¿A quién corresponde enjuiciar la responsabilidad contable de quienes manejan caudales públicos en Navarra?','["A la Cámara de Comptos", "Al Parlamento de Navarra", "Al Tribunal Superior de Justicia de Navarra", "Al Tribunal de Cuentas"]'::jsonb,3,'Art. 18 bis LORAFNA','Corresponde al Tribunal de Cuentas; si la Cámara de Comptos advierte indicios, le da traslado de las actuaciones.',null),
('admin-navarra:9-4786be4c0d','admin-navarra',9,'¿Qué función corresponde al Defensor del Pueblo de Navarra según la LORAFNA?','["La defensa de los derechos y libertades en el ámbito competencial de la Comunidad Foral, supervisando a sus Administraciones", "El asesoramiento jurídico al Gobierno de Navarra", "La resolución de los conflictos de competencia entre la Comunidad Foral y el Estado", "La fiscalización externa de las cuentas públicas"]'::jsonb,0,'Art. 18 ter LORAFNA','Le corresponde la defensa y protección de los derechos y libertades en el ámbito competencial foral, pudiendo supervisar a las Administraciones navarras.',null),
('admin-navarra:9-88031fda56','admin-navarra',9,'¿Ante quién da cuenta de sus actuaciones el Defensor del Pueblo de Navarra?','["Ante el Gobierno de Navarra", "Ante el Parlamento de Navarra", "Ante el Consejo de Navarra", "Ante el Defensor del Pueblo estatal"]'::jsonb,1,'Art. 18 ter LORAFNA','Es un órgano dependiente del Parlamento de Navarra, al que debe dar cuenta de sus actuaciones.',null),
('admin-navarra:9-337dff1371','admin-navarra',9,'¿Qué requisito tienen los ayuntamientos para ejercer la iniciativa legislativa foral?','["Representar un tercio de los municipios de la merindad y el 50 % de su población de derecho", "Representar la mitad de los municipios de Navarra y un tercio de su población de derecho", "Aprobarla por unanimidad de sus plenos", "Contar con el apoyo de la Federación Navarra de Municipios"]'::jsonb,0,'Art. 19 LORAFNA','Pueden ejercerla los ayuntamientos que representen un tercio de los municipios de la merindad y un cincuenta por ciento de su población de derecho.',null),
('admin-navarra:9-210f71fb93','admin-navarra',9,'¿Qué mayoría exige, con carácter general, la aprobación de las leyes forales?','["Mayoría absoluta", "Mayoría de tres quintos", "Mayoría de dos tercios", "Mayoría simple"]'::jsonb,3,'Art. 20 LORAFNA','Las leyes forales se aprueban por mayoría simple, salvo las que requieren mayoría absoluta.',null),
('admin-navarra:9-7b43feedd6','admin-navarra',9,'¿En qué plazo debe publicar el Presidente las leyes forales en el Boletín Oficial de Navarra?','["Quince días desde su aprobación", "Un mes desde su aprobación", "Veinte días desde su sanción", "Diez días desde su aprobación"]'::jsonb,0,'Art. 22 LORAFNA','El Presidente dispondrá su publicación en el BON en quince días desde su aprobación, y en el BOE; la entrada en vigor se rige por la publicación en el BON.',null),
('admin-navarra:10-f9c1e70f07','admin-navarra',10,'Según la LORAFNA, ¿qué funciones corresponden al Gobierno de Navarra o Diputación Foral?','["La potestad legislativa ordinaria, la aprobación de las Cuentas y el control de los Presupuestos", "La fiscalización externa del sector público", "La función ejecutiva, incluida la reglamentaria y la administrativa, y la revisora previa a la judicial", "El control de la acción del Parlamento"]'::jsonb,2,'Art. 23 LORAFNA','Le corresponde la función ejecutiva (reglamentaria y administrativa), la facultad revisora previa a la judicial y las demás que le atribuyan las leyes.',null),
('admin-navarra:10-da5caa491c','admin-navarra',10,'¿Qué forma adoptan las disposiciones generales dictadas por los consejeros del Gobierno de Navarra?','["Decretos Forales", "Órdenes Forales", "Acuerdos Forales", "Resoluciones Forales"]'::jsonb,1,'Art. 23 LORAFNA','Las del Presidente adoptan la forma de Decreto Foral del Presidente; las del Gobierno, Decreto Foral; y las de los consejeros, Órdenes Forales.',null),
('admin-navarra:10-d6a9122d91','admin-navarra',10,'¿Qué debe hacer la Diputación ante cualquier contrafuero?','["Convocar a la Junta de Cooperación en todo caso", "Dar cuenta al Parlamento", "Recurrir ante el Tribunal Supremo", "Comunicarlo al Delegado del Gobierno"]'::jsonb,1,'Art. 24 LORAFNA','La Diputación vela por la integridad del régimen foral y debe dar cuenta al Parlamento de cualquier contrafuero.',null),
('admin-navarra:10-aac9fe00bf','admin-navarra',10,'¿Para cuál de estas actuaciones precisa la Diputación Foral autorización previa del Parlamento?','["Resolver recursos de alzada", "Nombrar a los directores generales", "Emitir deuda pública, constituir avales y contraer crédito", "Aprobar reglamentos ejecutivos"]'::jsonb,2,'Art. 26 LORAFNA','Necesita autorización previa para emitir deuda, constituir avales y contraer crédito, entre otros supuestos.',null),
('admin-navarra:10-41c6903af4','admin-navarra',10,'¿Ante qué tribunal es exigible la responsabilidad criminal del Presidente y de los miembros de la Diputación Foral?','["El Tribunal Constitucional", "El Tribunal Superior de Justicia de Navarra", "La Audiencia Provincial de Navarra", "La Sala correspondiente del Tribunal Supremo"]'::jsonb,3,'Art. 27 LORAFNA','La responsabilidad criminal del Presidente y demás miembros de la Diputación es exigible ante la Sala correspondiente del Tribunal Supremo.',null),
('admin-navarra:10-34c690f31f','admin-navarra',10,'¿Cuándo cesa la Diputación Foral según la LORAFNA?','["Tras elecciones, al negarle el Parlamento la confianza o aprobar una censura, o por dimisión o fallecimiento del Presidente", "Cuando lo acuerde el Consejo de Navarra", "Solo al finalizar la legislatura", "Cuando dimita la mitad de sus consejeros o lo acuerde el Parlamento por mayoría simple"]'::jsonb,0,'Art. 28 LORAFNA','Cesa tras las elecciones, cuando el Parlamento le niegue la confianza o apruebe una moción de censura, o por dimisión o fallecimiento del Presidente.',null),
('admin-navarra:10-48136bf566','admin-navarra',10,'¿Qué es el Consejo de Navarra según la LORAFNA?','["El órgano de coordinación con el Estado", "La cámara alta del Parlamento de Navarra", "El órgano de gobierno de los municipios navarros", "El órgano consultivo superior de la Comunidad Foral"]'::jsonb,3,'Art. 28 ter LORAFNA','El Consejo de Navarra es el órgano consultivo superior, con autonomía orgánica y funcional.',null),
('admin-navarra:10-4d585257f3','admin-navarra',10,'¿Quién elige al Presidente de la Comunidad Foral de Navarra?','["Los ciudadanos por sufragio directo", "El Parlamento, de entre sus miembros, y lo nombra el Rey", "La Diputación Foral, de entre sus consejeros", "Las Cortes Generales a propuesta del Parlamento"]'::jsonb,1,'Art. 29 LORAFNA','El Presidente es elegido por el Parlamento de entre sus miembros y nombrado por el Rey.',null),
('admin-navarra:10-e94bc21b97','admin-navarra',10,'En la elección del Presidente de Navarra, ¿qué mayoría basta en segunda votación?','["Mayoría simple, veinticuatro horas después de la primera", "Mayoría simple, una semana después", "Mayoría absoluta, cuarenta y ocho horas después", "Mayoría de tres quintos"]'::jsonb,0,'Art. 29 LORAFNA','En primera votación se exige mayoría absoluta; si no, en segunda votación, veinticuatro horas después, basta la mayoría simple.',null),
('admin-navarra:10-46569b360c','admin-navarra',10,'Si en tres meses desde las elecciones no se elige Presidente, ¿qué ocurre?','["Asume la presidencia el Presidente del Parlamento", "Es elegido el candidato del partido más votado", "El Parlamento queda disuelto y se convocan nuevas elecciones", "El Rey nombra un Presidente interino"]'::jsonb,2,'Art. 29 LORAFNA','Transcurridos tres meses sin elegir Presidente, el Parlamento queda disuelto y se convocan de inmediato nuevas elecciones.',null),
('admin-navarra:10-16ff662009','admin-navarra',10,'¿Qué representación ostenta el Presidente de la Comunidad Foral de Navarra?','["La más alta representación de Navarra y la ordinaria del Estado en Navarra", "La representación del Parlamento de Navarra ante el Estado y ante las demás comunidades autónomas", "La representación de los municipios navarros", "Solo la representación del Gobierno de Navarra"]'::jsonb,0,'Art. 30 LORAFNA','Ostenta la más alta representación de la Comunidad Foral y la ordinaria del Estado en Navarra.',null),
('admin-navarra:10-252b792ff2','admin-navarra',10,'¿Cuándo NO puede el Presidente de Navarra acordar la disolución anticipada del Parlamento?','["Cuando lo pida la oposición", "Cuando el Gobierno haya presentado los presupuestos", "Cuando hayan pasado dos años de legislatura", "Cuando reste menos de un año para el fin de la legislatura"]'::jsonb,3,'Art. 30 LORAFNA','No puede disolver en el primer periodo de sesiones, cuando reste menos de un año, con moción de censura en trámite, con elecciones estatales convocadas ni antes de un año desde la última disolución.',null),
('admin-navarra:10-4abdf41349','admin-navarra',10,'¿Cómo responden el Presidente y los consejeros ante el Parlamento de su gestión política?','["Individualmente, cada uno por su departamento", "Solidariamente", "Solo responde el Presidente", "Mancomunadamente"]'::jsonb,1,'Art. 31 LORAFNA','El Presidente y los consejeros responden solidariamente ante el Parlamento de su gestión política.',null),
('admin-navarra:10-7dd058b35c','admin-navarra',10,'¿Qué mayoría se exige para otorgar la confianza al Presidente de Navarra en una cuestión de confianza?','["Mayoría de dos tercios", "Mayoría absoluta", "Mayoría simple", "Mayoría de tres quintos"]'::jsonb,2,'Art. 34 LORAFNA','La confianza se entiende otorgada cuando vota a favor la mayoría simple de los parlamentarios forales.',null),
('admin-navarra:10-c550f3a8f6','admin-navarra',10,'¿Qué mayoría exige la aprobación de una moción de censura en el Parlamento de Navarra?','["Mayoría simple", "Mayoría de dos tercios", "Mayoría de tres quintos", "Mayoría absoluta"]'::jsonb,3,'Art. 35 LORAFNA','El Parlamento exige la responsabilidad política del Gobierno mediante la aprobación por mayoría absoluta de una moción de censura.',null),
('admin-navarra:10-836e5bbf58','admin-navarra',10,'¿Qué número mínimo de parlamentarios debe proponer una moción de censura en Navarra?','["La mitad", "Una décima parte", "Una quinta parte", "Una tercera parte"]'::jsonb,2,'Art. 35 LORAFNA','La moción debe ser propuesta, al menos, por una quinta parte de los miembros del Parlamento e incluir un candidato a la Presidencia.',null),
('admin-navarra:10-7796583cd5','admin-navarra',10,'¿A qué control están sujetas las leyes forales de Navarra?','["Al control de la jurisdicción contencioso-administrativa y, en su caso, del Tribunal Constitucional", "Solo al control de constitucionalidad del Tribunal Constitucional", "Al control del Consejo de Navarra", "Al control previo del Gobierno de la Nación"]'::jsonb,1,'Art. 37 LORAFNA','Las leyes forales únicamente están sujetas al control de constitucionalidad del Tribunal Constitucional.',null),
('admin-navarra:10-4dfdd04f62','admin-navarra',10,'Según la Ley Foral 14/2004, ¿de quiénes se compone el Gobierno de Navarra?','["Del Presidente y los Consejeros", "Del Presidente, los Consejeros y el Portavoz del Gobierno", "Del Presidente, los Vicepresidentes y los Directores Generales", "Del Presidente, los Consejeros y los Secretarios Generales Técnicos"]'::jsonb,0,'Art. 4 LF 14/2004 Navarra','El Gobierno de Navarra se compone de su Presidente y los Consejeros.',null),
('admin-navarra:10-1ddda54856','admin-navarra',10,'¿Cuándo queda constituido el Gobierno de Navarra?','["Cuando se publica en el BON la estructura de los Departamentos", "Cuando el Parlamento otorga su confianza al programa", "Cuando los Consejeros han tomado posesión de sus cargos", "Cuando el Rey nombra al Presidente del Gobierno"]'::jsonb,2,'Art. 5 LF 14/2004 Navarra','El Gobierno queda constituido una vez que los Consejeros hayan tomado posesión de sus cargos (art. 40).',null),
('admin-navarra:10-e83881b4cf','admin-navarra',10,'¿Qué delegaciones legislativas se mantienen mientras el Gobierno de Navarra está en funciones?','["Las que afecten a materias presupuestarias y a la Ley Foral de Presupuestos Generales", "Ninguna, quedan todas en suspenso sin excepción", "Todas las otorgadas antes de las elecciones", "Las referentes a los Decretos Forales Legislativos de armonización tributaria"]'::jsonb,3,'Art. 6 LF 14/2004 Navarra','Quedan en suspenso las delegaciones legislativas, con excepción de las referentes a los Decretos Forales Legislativos de armonización tributaria.',null),
('admin-navarra:10-f681ebd8d7','admin-navarra',10,'¿A quién corresponde el mando supremo de la Policía Foral según la Ley Foral 14/2004?','["A la Junta de Seguridad de Navarra", "Al Gobierno de Navarra", "Al Presidente del Gobierno de Navarra en exclusiva", "Al Consejero competente en materia de interior"]'::jsonb,1,'Art. 7 LF 14/2004 Navarra','Entre las atribuciones del Gobierno de Navarra figura el mando supremo de la Policía Foral (art. 7.14).',null),
('admin-navarra:10-b467fde9d7','admin-navarra',10,'¿Qué quórum se exige para la válida adopción de acuerdos del Gobierno de Navarra?','["El Presidente, o quien le sustituya, y al menos la mitad de los Consejeros", "El Presidente, el Consejero Secretario del Gobierno y, al menos, un tercio de los Consejeros", "El Presidente y al menos dos tercios de los Consejeros", "La mayoría absoluta de los Consejeros, con o sin el Presidente"]'::jsonb,0,'Art. 8 LF 14/2004 Navarra','Es necesaria la asistencia del Presidente, o quien legalmente le sustituya, y al menos la mitad de los Consejeros.',null),
('admin-navarra:10-b50f0362c8','admin-navarra',10,'¿Qué carácter tienen las deliberaciones del Gobierno de Navarra?','["Público, salvo que el Presidente declare su reserva", "Secreto solo para los asuntos de seguridad pública", "Reservado y secreto, incluso después de cesar en el cargo", "Reservado solo mientras dure la legislatura en la que se celebró la sesión"]'::jsonb,2,'Art. 9 LF 14/2004 Navarra','Las deliberaciones tienen carácter reservado y secreto, y sus miembros deben mantenerlo aun después de cesar.',null),
('admin-navarra:10-1540a4eaa1','admin-navarra',10,'¿Hasta qué grado de parentesco obliga a abstenerse a los miembros del Gobierno de Navarra la Ley Foral 14/2004?','["Tercer grado de consanguinidad o segundo de afinidad", "Cuarto grado de consanguinidad o segundo de afinidad", "Cuarto grado de consanguinidad o tercero de afinidad", "Segundo grado de consanguinidad o primero de afinidad"]'::jsonb,1,'Art. 11 LF 14/2004 Navarra','Deben abstenerse si afecta a empresas de su cónyuge o familiares dentro del cuarto grado de consanguinidad o segundo de afinidad.',null),
('admin-navarra:10-77b4691315','admin-navarra',10,'¿Qué forma revisten las decisiones del Gobierno de Navarra que aprueban sus disposiciones reglamentarias?','["Decreto Foral", "Orden Foral", "Acuerdo", "Decreto Foral Legislativo"]'::jsonb,0,'Art. 12 LF 14/2004 Navarra','Adoptan la forma de Decreto Foral las disposiciones generales aprobadas en uso de la potestad reglamentaria.',null),
('admin-navarra:10-deae10a1a0','admin-navarra',10,'¿Quién firma los Acuerdos del Gobierno de Navarra?','["El Consejero que formuló la propuesta", "El titular del Secretariado del Gobierno", "El Presidente del Gobierno", "El Consejero Secretario"]'::jsonb,3,'Art. 12 LF 14/2004 Navarra','Los Acuerdos del Gobierno de Navarra son firmados por el Consejero Secretario.',null),
('admin-navarra:10-9103e2b329','admin-navarra',10,'¿Quién es el Consejero Secretario del Gobierno de Navarra?','["El Consejero que designe libremente el Parlamento", "El Vicepresidente primero del Gobierno o, si no lo hay, el Consejero de mayor antigüedad", "El Consejero de mayor edad", "El titular del Departamento al que corresponde la materia de Presidencia"]'::jsonb,3,'Art. 13 LF 14/2004 Navarra','Es Consejero Secretario el titular del Departamento al que corresponda la materia de Presidencia.',null),
('admin-navarra:10-f52050fcd1','admin-navarra',10,'Si el Portavoz del Gobierno de Navarra no es Consejero, ¿qué rango tiene?','["Secretario General Técnico", "Jefe de Servicio", "Director General", "Consejero sin cartera"]'::jsonb,2,'Art. 15 LF 14/2004 Navarra','En caso de no ser Consejero, el Portavoz tiene rango de Director General y depende directamente del Presidente.',null),
('admin-navarra:10-b6720d13cc','admin-navarra',10,'¿Quién preside la Comisión de Coordinación del Gobierno de Navarra?','["El titular del Secretariado del Gobierno", "El Consejero Secretario del Gobierno", "El Vicepresidente primero", "El Presidente del Gobierno de Navarra"]'::jsonb,1,'Art. 18 LF 14/2004 Navarra','En todo caso, será Presidente de la Comisión de Coordinación el Consejero Secretario del Gobierno.',null),
('admin-navarra:10-78ee8d285c','admin-navarra',10,'¿Puede la Comisión de Coordinación adoptar acuerdos por delegación del Gobierno de Navarra?','["No, en ningún caso", "Sí, durante los periodos vacacionales", "Sí, si lo autoriza el Presidente", "Sí, en asuntos de trámite"]'::jsonb,0,'Art. 18 LF 14/2004 Navarra','En ningún caso podrá la Comisión de Coordinación adoptar decisiones o acuerdos por delegación del Gobierno.',null),
('admin-navarra:10-bb1fd8092f','admin-navarra',10,'¿Qué consideración tienen los miembros de los gabinetes del Gobierno de Navarra?','["Personal laboral temporal", "Altos cargos de la Administración", "Personal eventual", "Funcionarios de libre designación"]'::jsonb,2,'Art. 19 LF 14/2004 Navarra','Son nombrados y cesados libremente y tienen la consideración de personal eventual.',null),
('admin-navarra:10-b19da7e864','admin-navarra',10,'¿En qué plazo debe tomar posesión el Presidente del Gobierno de Navarra?','["Quince días hábiles desde su elección por el Parlamento", "Un mes desde la publicación del real decreto de nombramiento en el Boletín Oficial del Estado", "Cinco días desde la publicación de su nombramiento en el BOE", "Diez días naturales desde la publicación de su nombramiento en el BON"]'::jsonb,3,'Art. 25 LF 14/2004 Navarra','Dentro de los diez días naturales siguientes a la publicación de su nombramiento en el BON toma posesión ante el Presidente del Parlamento.',null),
('admin-navarra:10-56107d97d3','admin-navarra',10,'¿Ante quién toma posesión el Presidente del Gobierno de Navarra?','["Ante el Presidente del Parlamento de Navarra", "Ante el Pleno del Tribunal Superior de Justicia", "Ante el Delegado del Gobierno en Navarra", "Ante el Rey"]'::jsonb,0,'Art. 25 LF 14/2004 Navarra','Toma posesión ante el Presidente del Parlamento de Navarra, mediante juramento o promesa.',null),
('admin-navarra:10-7c46ab6896','admin-navarra',10,'A falta de Vicepresidentes, ¿quién suple al Presidente del Gobierno de Navarra en caso de ausencia o enfermedad?','["El Presidente del Parlamento de Navarra", "El Consejero más antiguo que sea Parlamentario Foral", "El Consejero de más edad", "El Consejero Secretario del Gobierno"]'::jsonb,1,'Art. 26 LF 14/2004 Navarra','Le suple un Vicepresidente por su orden; a falta de ellos, el Consejero más antiguo que sea Parlamentario Foral; si ninguno lo es, el más antiguo en el cargo.',null),
('admin-navarra:10-1e367d996a','admin-navarra',10,'¿Qué facultad NO puede ejercer quien supla interinamente al Presidente del Gobierno de Navarra?','["Disolver el Parlamento de Navarra", "Presidir las sesiones del Gobierno", "Representar a la Comunidad Foral", "Firmar Decretos Forales"]'::jsonb,0,'Art. 26 LF 14/2004 Navarra','No puede plantear la cuestión de confianza, disolver el Parlamento ni cesar a los miembros del Gobierno.',null),
('admin-navarra:10-e52f7c017d','admin-navarra',10,'¿Qué mayoría del Gobierno de Navarra exige apreciar la incapacidad permanente del Presidente?','["Dos tercios de sus miembros", "Mayoría absoluta de sus miembros", "Al menos cuatro quintas partes de sus miembros", "Tres quintas partes de sus miembros"]'::jsonb,2,'Art. 27 LF 14/2004 Navarra','Debe apreciarla el Gobierno por al menos cuatro quintas partes y declararla el Parlamento por mayoría absoluta.',null),
('admin-navarra:10-bc1e61f27e','admin-navarra',10,'¿Qué facultad NO tiene el Presidente del Gobierno de Navarra en funciones?','["Convocar las sesiones del Gobierno", "Nombrar y cesar a los Consejeros", "Firmar los Decretos Forales", "Ostentar la representación de Navarra"]'::jsonb,1,'Art. 28 LF 14/2004 Navarra','El Presidente en funciones no puede nombrar ni cesar Consejeros, crear o suprimir Departamentos ni plantear la cuestión de confianza.',null),
('admin-navarra:10-4e3f670d23','admin-navarra',10,'¿Cuál de estas atribuciones del Presidente del Gobierno de Navarra es delegable?','["Nombrar y cesar a los Consejeros", "Convocar elecciones al Parlamento", "Crear y suprimir Departamentos", "Autorizar gastos y pagos en los casos legales"]'::jsonb,3,'Art. 31 LF 14/2004 Navarra','No son delegables las de los apartados 2 a 8 y 11 del art. 30; la autorización de gastos y pagos (apartado 12) sí lo es.',null),
('admin-navarra:10-cc28bbf503','admin-navarra',10,'¿Qué forma adopta el acto por el que el Presidente de Navarra nombra a los Consejeros?','["Resolución de Presidencia", "Orden Foral", "Decreto Foral del Presidente", "Acuerdo del Gobierno"]'::jsonb,2,'Art. 32 LF 14/2004 Navarra','Las atribuciones de convocar elecciones, disolver, crear Departamentos y nombrar Consejeros se ejercen por Decreto Foral del Presidente.',null),
('admin-navarra:10-10b10c42c9','admin-navarra',10,'¿Dónde se fijan las retribuciones del Presidente y de los Consejeros del Gobierno de Navarra?','["En la Ley Foral de incompatibilidades", "En una resolución de la Mesa del Parlamento", "En un Decreto Foral del propio Gobierno", "En la Ley Foral de Presupuestos Generales de Navarra"]'::jsonb,3,'Art. 35 LF 14/2004 Navarra','Se fijan de forma expresa y cuantitativa en la Ley Foral de Presupuestos Generales de Navarra.',null),
('admin-navarra:10-256ae06082','admin-navarra',10,'¿Quién nombra a los Consejeros del Gobierno de Navarra?','["El Gobierno en pleno", "Libremente el Presidente del Gobierno", "El Rey a propuesta del Presidente", "El Parlamento a propuesta del Presidente"]'::jsonb,1,'Art. 40 LF 14/2004 Navarra','Los Consejeros son nombrados libremente por el Presidente del Gobierno de Navarra.',null),
('admin-navarra:10-4d53a7a486','admin-navarra',10,'¿Cuál de estas atribuciones de los Consejeros es delegable?','["Autorizar gastos y pagos en los casos legales", "Formular el anteproyecto de presupuesto del Departamento", "Ejercer la potestad reglamentaria", "Dictar Órdenes Forales"]'::jsonb,0,'Art. 41 LF 14/2004 Navarra','No pueden delegar, entre otras, las letras d), e), f), g), i), j) y k); la autorización de gastos (letra l) sí.',null),
('admin-navarra:10-ce88400d61','admin-navarra',10,'¿Quién puede suplir a un Consejero en caso de ausencia o enfermedad?','["El Secretario General Técnico del Departamento", "El Director General de mayor antigüedad", "Solo otro Consejero, designado por Decreto Foral del Presidente", "Cualquier alto cargo de su Departamento que designe el propio Consejero mediante orden foral"]'::jsonb,2,'Art. 48 LF 14/2004 Navarra','Los Consejeros solo pueden ser suplidos por otros Consejeros; la suplencia la determina el Presidente por Decreto Foral.',null),
('admin-navarra:10-10cb13249d','admin-navarra',10,'¿Desde cuándo surte efectos el cese de un Consejero por dimisión?','["Desde que lo acepta el Gobierno en pleno, mediante acuerdo publicado en el BON", "Desde la toma de posesión de quien le sustituya", "Desde que presenta su escrito de dimisión", "Desde la publicación en el BON del Decreto Foral del Presidente"]'::jsonb,3,'Art. 49 LF 14/2004 Navarra','En la dimisión y la separación, el cese surte efectos desde la publicación en el BON del Decreto Foral del Presidente.',null),
('admin-navarra:11-2663ed9c3c','admin-navarra',11,'Según el art. 1.1 del Código Civil, las fuentes del ordenamiento jurídico español son:','["La ley, la costumbre y los principios generales del derecho", "La ley, la jurisprudencia del Tribunal Supremo y los principios generales del derecho", "La ley, la costumbre y la jurisprudencia", "La Constitución, la ley y la costumbre"]'::jsonb,0,'Art. 1.1 CC','Las fuentes son la ley, la costumbre y los principios generales del derecho.',null),
('admin-navarra:11-771e1024e4','admin-navarra',11,'Según el Código Civil, las disposiciones que contradigan otra de rango superior:','["Son válidas si son posteriores", "Carecerán de validez", "Prevalecen si son más específicas", "Solo son anulables a instancia de parte"]'::jsonb,1,'Art. 1.2 CC','Carecerán de validez las disposiciones que contradigan otra de rango superior.',null),
('admin-navarra:11-b32ef00fa5','admin-navarra',11,'La costumbre rige:','["En defecto de ley aplicable, aunque sea contraria a la moral, siempre que resulte probada ante el juez", "En igualdad de rango con la ley, siempre que resulte probada y no sea contraria al orden público ni a la moral", "En defecto de ley aplicable, si no es contraria a la moral ni al orden público y resulta probada", "Solo cuando la reconozca expresamente una sentencia firme del Tribunal Supremo"]'::jsonb,2,'Art. 1.3 CC','La costumbre solo rige en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público y que resulte probada.',null),
('admin-navarra:11-269ebe326f','admin-navarra',11,'Los principios generales del derecho se aplican:','["Antes que la costumbre, por su carácter informador de todo el ordenamiento jurídico", "Solo cuando así lo prevea expresamente una ley", "En igualdad de rango con la ley y con la costumbre, según el caso concreto", "En defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento"]'::jsonb,3,'Art. 1.4 CC','Se aplican en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.',null),
('admin-navarra:11-8b29fb8c06','admin-navarra',11,'Según el Código Civil, la jurisprudencia:','["Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo", "Es fuente directa del ordenamiento, al mismo nivel que la ley", "Complementa el ordenamiento con la doctrina de cualquier juzgado o tribunal", "Complementa el ordenamiento con la doctrina reiterada del Tribunal Constitucional"]'::jsonb,0,'Art. 1.6 CC','Complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales.',null),
('admin-navarra:11-2a831ed882','admin-navarra',11,'Los jueces y tribunales, ante un asunto del que conozcan:','["Pueden abstenerse de resolver si no encuentran ley aplicable", "Tienen el deber inexcusable de resolver, ateniéndose al sistema de fuentes", "Tienen el deber de resolver solo si existe ley o jurisprudencia previa", "Deben elevar consulta al Tribunal Supremo si no hay ley aplicable"]'::jsonb,1,'Art. 1.7 CC','Tienen el deber inexcusable de resolver en todo caso, ateniéndose al sistema de fuentes establecido.',null),
('admin-navarra:11-db1b596382','admin-navarra',11,'Si una ley no dice otra cosa, ¿cuándo entra en vigor?','["Al día siguiente de su completa publicación en el BOE", "Al mes de su completa publicación en el Boletín Oficial del Estado", "A los veinte días de su completa publicación en el BOE", "A los quince días hábiles de su completa publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Art. 2.1 CC','Las leyes entran en vigor a los veinte días de su completa publicación en el BOE, si en ellas no se dispone otra cosa.',null),
('admin-navarra:11-bc61feb1a9','admin-navarra',11,'Según el Código Civil, las leyes se derogan:','["Por el desuso", "Por la costumbre contraria", "Por sentencia de cualquier juez", "Solo por otras leyes posteriores"]'::jsonb,3,'Art. 2.2 CC','Las leyes solo se derogan por otras posteriores.',null),
('admin-navarra:11-50d7c616e0','admin-navarra',11,'Según el Código Civil, las leyes:','["No tienen efecto retroactivo si no dispusieren lo contrario", "Tienen efecto retroactivo si no dispusieren lo contrario", "No pueden tener efecto retroactivo en ningún caso, aunque lo disponga expresamente la propia ley", "Solo tienen efecto retroactivo si son favorables y así lo dicen"]'::jsonb,0,'Art. 2.3 CC','Las leyes no tienen efecto retroactivo si no dispusieren lo contrario.',null),
('admin-navarra:11-bb7f029dd7','admin-navarra',11,'La ignorancia de las leyes:','["Excusa de su cumplimiento", "No excusa de su cumplimiento", "Excusa solo a los extranjeros", "Excusa durante el primer año de vigencia"]'::jsonb,1,'Art. 6.1 CC','La ignorancia de las leyes no excusa de su cumplimiento.',null),
('admin-navarra:11-e9b7101ac1','admin-navarra',11,'Son leyes orgánicas, entre otras, las relativas a:','["Los presupuestos generales del Estado, los Estatutos de Autonomía, el régimen electoral y los tributos", "El desarrollo de los derechos fundamentales, el sistema tributario y las bases del régimen local", "Las bases del régimen local, los Estatutos de Autonomía y el régimen electoral", "El desarrollo de los derechos fundamentales, los Estatutos de Autonomía y el régimen electoral"]'::jsonb,3,'Art. 81.1 CE','Son orgánicas las relativas al desarrollo de los derechos fundamentales y libertades públicas, las que aprueban los Estatutos de Autonomía y el régimen electoral general, y las demás previstas en la Constitución.',null),
('admin-navarra:11-7174dc05c7','admin-navarra',11,'La aprobación, modificación o derogación de las leyes orgánicas exige:','["Mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto", "Mayoría absoluta de ambas Cámaras en una votación final sobre el conjunto", "Mayoría de tres quintos del Congreso en una votación final sobre el conjunto", "Mayoría absoluta del Congreso en la votación de cada uno de los artículos"]'::jsonb,0,'Art. 81.2 CE','Exige mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto.',null),
('admin-navarra:11-b84cc6e43b','admin-navarra',11,'¿Puede delegarse en el Gobierno la potestad de dictar normas con rango de ley sobre materias reservadas a ley orgánica?','["Sí, siempre", "No", "Sí, con autorización del Rey", "Sí, mediante ley de bases"]'::jsonb,1,'Art. 82.1 CE','La delegación solo cabe en materias que no sean objeto de ley orgánica.',null),
('admin-navarra:11-735627b855','admin-navarra',11,'¿Qué ley se usa para delegar la formación de textos articulados?','["Una ley orgánica", "Un decreto-ley", "Una ley de bases", "Una ley ordinaria de refundición"]'::jsonb,2,'Art. 82.2 CE','Para textos articulados se usa una ley de bases; para refundir varios textos legales, una ley ordinaria.',null),
('admin-navarra:11-0c847aa3c7','admin-navarra',11,'La delegación legislativa al Gobierno:','["Puede ser expresa o implícita, para materia concreta y con plazo", "Debe ser expresa, para materia concreta, y puede darse por tiempo indefinido", "Debe ser expresa y puede subdelegarse en los ministros", "Debe ser expresa, para materia concreta y con fijación del plazo"]'::jsonb,3,'Art. 82.3 CE','Debe otorgarse de forma expresa, para materia concreta y con plazo; no puede ser implícita, indefinida ni subdelegarse a autoridades distintas del Gobierno.',null),
('admin-navarra:11-bde7490216','admin-navarra',11,'Las disposiciones del Gobierno que contienen legislación delegada se denominan:','["Decretos Legislativos", "Decretos-leyes", "Reales Decretos", "Órdenes ministeriales"]'::jsonb,0,'Art. 85 CE','Reciben el título de Decretos Legislativos.',null),
('admin-navarra:11-d34c85144a','admin-navarra',11,'El Gobierno puede dictar decretos-leyes:','["En cualquier materia y circunstancia", "En caso de extraordinaria y urgente necesidad", "Solo con autorización previa del Congreso", "Solo durante el estado de alarma"]'::jsonb,1,'Art. 86.1 CE','Puede dictarlos en caso de extraordinaria y urgente necesidad, como disposiciones legislativas provisionales.',null),
('admin-navarra:11-81f7bc3b89','admin-navarra',11,'Un decreto-ley NO puede afectar a:','["Las medidas económicas urgentes", "La organización de servicios administrativos", "El régimen de las Comunidades Autónomas", "Las ayudas a sectores afectados por una catástrofe"]'::jsonb,2,'Art. 86.1 CE','No puede afectar al ordenamiento de las instituciones básicas del Estado, a los derechos del Título I, al régimen de las CCAA ni al Derecho electoral general.',null),
('admin-navarra:11-dac2ff1110','admin-navarra',11,'¿En qué plazo debe someterse un decreto-ley a debate y votación de totalidad en el Congreso?','["Quince días siguientes a su promulgación", "Un mes siguiente a su publicación en el Boletín Oficial del Estado", "Sesenta días siguientes a su promulgación", "Treinta días siguientes a su promulgación"]'::jsonb,3,'Art. 86.2 CE','Debe someterse a debate y votación de totalidad en los treinta días siguientes a su promulgación.',null),
('admin-navarra:11-4f8c91d0c3','admin-navarra',11,'Las leyes de bases NO pueden:','["Fijar los principios y criterios que han de seguirse en el ejercicio de la delegación", "Autorizar su propia modificación ni facultar para dictar normas con carácter retroactivo", "Delimitar con precisión el objeto y el alcance de la delegación legislativa", "Fijar el plazo para el ejercicio de la delegación"]'::jsonb,1,'Art. 83 CE','Las leyes de bases no pueden autorizar la modificación de la propia ley de bases ni facultar para dictar normas con carácter retroactivo (art. 83 CE). Sí deben delimitar el objeto y alcance, fijar los principios y criterios (art. 82.4) y el plazo (art. 82.3).',null),
('admin-navarra:11-b295b41f98','admin-navarra',11,'Durante el plazo de convalidación, las Cortes pueden tramitar los decretos-leyes:','["Como proposiciones de ley por el procedimiento ordinario", "Como proyectos de ley por el procedimiento de urgencia", "Como leyes orgánicas por el procedimiento de lectura única", "Como decretos legislativos sujetos a control parlamentario"]'::jsonb,1,'Art. 86.3 CE','Durante el plazo de treinta días, las Cortes pueden tramitarlos como proyectos de ley por el procedimiento de urgencia.',null),
('admin-navarra:11-3ae4ed8624','admin-navarra',11,'Según el Código Civil, las normas jurídicas contenidas en los tratados internacionales serán de aplicación directa en España:','["Cuando hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE", "Desde su ratificación por el Rey, aunque la publicación en el BOE sea solo de un extracto", "Desde su firma por el Gobierno, aunque todavía no se hayan publicado en ningún diario oficial", "A los veinte días de su publicación en el Diario Oficial de la Unión Europea, en todo caso"]'::jsonb,0,'Art. 1.5 CC','El art. 1.5 CC exige que hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en el BOE.',null),
('admin-navarra:11-4800edb6ab','admin-navarra',11,'Según el art. 3.1 del Código Civil, las normas se interpretarán atendiendo fundamentalmente a:','["Su sentido literal", "Sus antecedentes históricos", "Su espíritu y finalidad", "La realidad social del momento en que se aprobaron"]'::jsonb,2,'Art. 3.1 CC','Se atiende al sentido de las palabras, el contexto, los antecedentes y la realidad social, pero fundamentalmente al espíritu y finalidad.',null),
('admin-navarra:11-ecdec99689','admin-navarra',11,'Según el Código Civil, las resoluciones de los tribunales solo podrán descansar de manera exclusiva en la equidad:','["Cuando no exista costumbre aplicable al caso", "Cuando las partes lo soliciten de común acuerdo", "Cuando la ley expresamente lo permita", "En los asuntos de cuantía inferior a 6.000 euros"]'::jsonb,2,'Art. 3.2 CC','La equidad se pondera en la aplicación de las normas, pero las resoluciones solo pueden basarse exclusivamente en ella cuando la ley lo permita.',null),
('admin-navarra:11-d04eedac29','admin-navarra',11,'Procede la aplicación analógica de las normas cuando estas no contemplen un supuesto específico, pero regulen otro semejante:','["Siempre que se trate de normas penales o sancionadoras", "Aunque no exista identidad de razón entre ambos", "Solo si así lo acuerda la jurisprudencia del Tribunal Supremo", "Entre los que se aprecie identidad de razón"]'::jsonb,3,'Art. 4.1 CC','El art. 4.1 CC exige que entre el supuesto regulado y el no regulado se aprecie identidad de razón.',null),
('admin-navarra:11-958609d31f','admin-navarra',11,'Según el Código Civil, ¿qué leyes NO se aplicarán a supuestos ni en momentos distintos de los comprendidos expresamente en ellas?','["Las orgánicas, las ordinarias y los decretos legislativos", "Las penales, las excepcionales y las de ámbito temporal", "Las de bases, las de armonización y los decretos-leyes", "Las autonómicas, las forales y las de régimen local"]'::jsonb,1,'Art. 4.2 CC','Las leyes penales, las excepcionales y las de ámbito temporal no admiten aplicación analógica.',null),
('admin-navarra:11-dcec655728','admin-navarra',11,'Las disposiciones del Código Civil se aplicarán en las materias regidas por otras leyes:','["Como supletorias", "Solo en defecto de costumbre", "Con carácter preferente", "Solo si lo prevé la otra ley"]'::jsonb,0,'Art. 4.3 CC','El art. 4.3 CC establece la aplicación supletoria del Código Civil en las materias regidas por otras leyes.',null),
('admin-navarra:11-800d2cfd1a','admin-navarra',11,'En el cómputo civil de los plazos, según el Código Civil:','["Se excluyen los días inhábiles del mes de agosto", "No se excluyen los días inhábiles", "Se excluyen los sábados y domingos", "Se excluyen solo los días festivos nacionales"]'::jsonb,1,'Art. 5.2 CC','A diferencia del cómputo administrativo, en el cómputo civil no se excluyen los días inhábiles.',null),
('admin-navarra:11-986fc59466','admin-navarra',11,'La exclusión voluntaria de la ley aplicable y la renuncia a los derechos en ella reconocidos solo serán válidas:','["Cuando las autorice previamente el juez del domicilio del renunciante", "Cuando consten en documento público otorgado ante notario, en todo caso", "Cuando se refieran a derechos patrimoniales de cuantía inferior a 3.000 euros", "Cuando no contraríen el interés o el orden público ni perjudiquen a terceros"]'::jsonb,3,'Art. 6.2 CC','El art. 6.2 CC solo admite la exclusión o renuncia si no contraría el interés o el orden público ni perjudica a terceros.',null),
('admin-navarra:11-1dad8ee2cf','admin-navarra',11,'Según el Código Civil, los actos contrarios a las normas imperativas y a las prohibitivas son:','["Anulables a instancia de parte durante el plazo de cuatro años desde su celebración", "Nulos de pleno derecho en todo caso, sin que la norma pueda prever otro efecto", "Nulos de pleno derecho, salvo que en ellas se establezca un efecto distinto para el caso de contravención", "Válidos, aunque quien los realiza debe indemnizar los daños y perjuicios causados"]'::jsonb,2,'Art. 6.3 CC','Son nulos de pleno derecho, salvo que la norma establezca un efecto distinto para el caso de contravención.',null),
('admin-navarra:11-01ec47df53','admin-navarra',11,'Los actos realizados al amparo de una norma que persigan un resultado prohibido por el ordenamiento se consideran ejecutados en fraude de ley y:','["No impedirán la debida aplicación de la norma que se hubiere tratado de eludir", "Serán válidos si la norma de cobertura tiene rango de ley", "Darán lugar siempre a responsabilidad penal de sus autores", "Producirán efectos hasta que un juez declare su nulidad"]'::jsonb,0,'Art. 6.4 CC','El fraude de ley no impide la debida aplicación de la norma que se hubiere tratado de eludir.',null),
('admin-navarra:11-a325b7b882','admin-navarra',11,'Según el art. 7 del Código Civil, la ley no ampara:','["La aplicación supletoria del propio Código Civil", "La renuncia a derechos que no perjudique a terceros", "El ejercicio de los derechos conforme a la buena fe", "El abuso del derecho ni su ejercicio antisocial"]'::jsonb,3,'Art. 7.2 CC','El art. 7.2 CC: la ley no ampara el abuso del derecho o su ejercicio antisocial; el art. 7.1 exige ejercitar los derechos conforme a la buena fe.',null),
('admin-navarra:11-d5fbcc63bd','admin-navarra',11,'¿Puede el Parlamento delegar en la Diputación la potestad legislativa en materias que exigen mayoría absoluta?','["Sí, mediante ley de bases", "Sí, por un plazo máximo de un año", "No", "Sí, si lo solicita la Diputación"]'::jsonb,2,'Art. 21 LORAFNA','No procede la delegación en los supuestos en que se exija mayoría absoluta para la aprobación de las leyes forales.',null),
('admin-navarra:11-42c5ea10f7','admin-navarra',11,'¿En qué plazo deben convalidarse los decretos-leyes forales por el Parlamento de Navarra?','["En los quince días siguientes a su publicación", "En los treinta días siguientes a su promulgación", "En el siguiente periodo de sesiones", "En el plazo de dos meses"]'::jsonb,1,'Art. 21 bis LORAFNA','Quedan derogados si en el plazo improrrogable de treinta días no son convalidados expresamente por el Parlamento.',null),
('admin-navarra:11-024f113279','admin-navarra',11,'¿Cuál de estas materias NO puede regularse por decreto-ley foral?','["Ayudas extraordinarias por catástrofes", "Medidas urgentes en materia de vivienda", "Medidas urgentes de apoyo a sectores económicos", "Los Presupuestos Generales de Navarra"]'::jsonb,3,'Art. 21 bis LORAFNA','No pueden ser objeto de decreto-ley foral, entre otros, el régimen electoral y los Presupuestos Generales de Navarra.',null),
('admin-navarra:11-cb33cbf952','admin-navarra',11,'¿En qué plazo deben dictarse los Decretos Forales Legislativos de armonización tributaria?','["Dos meses desde la publicación de la modificación tributaria estatal", "Un mes desde la publicación de la modificación estatal", "Seis meses desde la publicación de la modificación estatal", "Tres meses desde la entrada en vigor de la norma estatal"]'::jsonb,0,'Art. 53 LF 14/2004 Navarra','Deben dictarse y publicarse en el plazo de dos meses desde la publicación de la modificación tributaria estatal.',null),
('admin-navarra:11-46f609573c','admin-navarra',11,'¿En qué plazo se remiten al Parlamento los Decretos Forales Legislativos de armonización tributaria?','["Quince días desde su publicación", "Diez días desde su aprobación", "Treinta días desde su aprobación", "Cinco días desde su entrada en vigor"]'::jsonb,1,'Art. 53 LF 14/2004 Navarra','Se remiten al Parlamento dentro de los diez días siguientes a su aprobación, para su control parlamentario.',null),
('admin-navarra:12-5009cac716','admin-navarra',12,'Según la Ley Foral 11/2019, ¿qué entidades tienen la consideración de Administración Pública Foral?','["La Administración de la Comunidad Foral, las entidades locales y la Universidad Pública", "Solo la Administración de la Comunidad Foral de Navarra", "La Administración de la Comunidad Foral y todas sus sociedades, fundaciones y consorcios públicos", "La Administración de la Comunidad Foral y sus organismos públicos y entidades de derecho público"]'::jsonb,3,'Art. 2 LF 11/2019 Navarra','Es Administración Pública Foral la Administración de la Comunidad Foral y los organismos públicos y entidades de derecho público vinculados o dependientes.',null),
('admin-navarra:12-b068423775','admin-navarra',12,'¿Cómo actúa la Administración de la Comunidad Foral de Navarra para el cumplimiento de sus fines?','["Con personalidad jurídica única", "Con una personalidad jurídica por cada Departamento", "Sin personalidad jurídica propia, como órgano del Gobierno", "Con personalidad jurídica limitada a sus relaciones con terceros"]'::jsonb,0,'Art. 3 LF 11/2019 Navarra','La Administración de la Comunidad Foral, constituida por órganos jerárquicamente ordenados, actúa con personalidad jurídica única.',null),
('admin-navarra:12-f8fb4dc5dd','admin-navarra',12,'¿Cuáles son los órganos superiores de la Administración Pública Foral?','["El Presidente, los Consejeros, los Directores Generales y los Secretarios Generales Técnicos", "Los Consejeros y los Directores Generales", "El Gobierno, su Presidente, los Vicepresidentes en su caso y los Consejeros", "El Gobierno, los Consejeros y los Directores Generales"]'::jsonb,2,'Art. 7 LF 11/2019 Navarra','Son órganos superiores el Gobierno de Navarra, su Presidente, los Vicepresidentes en su caso y los Consejeros.',null),
('admin-navarra:12-da3343ce6a','admin-navarra',12,'¿Afecta a la validez de un acto el incumplimiento de una instrucción u orden de servicio?','["Sí, el acto es nulo de pleno derecho", "No por sí solo, sin perjuicio de la responsabilidad disciplinaria", "Solo si la instrucción se publicó en el BON", "Sí, el acto es anulable en todo caso, aunque no cause indefensión al interesado"]'::jsonb,1,'Art. 9 LF 11/2019 Navarra','El incumplimiento de instrucciones u órdenes de servicio no afecta por sí solo a la validez de los actos, sin perjuicio de la responsabilidad disciplinaria.',null),
('admin-navarra:12-c5d3921d62','admin-navarra',12,'Si una competencia se atribuye genéricamente sin especificar Departamento y no puede atribuirse por la materia, ¿a quién corresponde?','["Al Departamento que designe el Parlamento", "Al Departamento competente en materia de hacienda", "Al Gobierno de Navarra en pleno", "Al Departamento que tenga la competencia de Presidencia"]'::jsonb,3,'Art. 10 LF 11/2019 Navarra','Si no puede entenderse atribuida a un Departamento concreto, se entiende atribuida al que tenga la competencia de Presidencia.',null),
('admin-navarra:12-e7b66f0629','admin-navarra',12,'Si una competencia de un Departamento no puede atribuirse a un órgano concreto, ¿a quién corresponde?','["A la persona titular del Servicio correspondiente por razón de la materia", "A la persona titular del Departamento", "A la Dirección General de mayor antigüedad", "A la persona titular de la Secretaría General Técnica"]'::jsonb,0,'Art. 10 LF 11/2019 Navarra','Se entiende que corresponde a la persona titular del Servicio correspondiente por razón de la materia, u órgano de rango equivalente.',null),
('admin-navarra:12-de50716af6','admin-navarra',12,'En la delegación interorgánica entre órganos no vinculados jerárquicamente, ¿qué se exige?','["El informe previo de la Secretaría General Técnica", "La autorización del Gobierno de Navarra", "La aprobación previa del superior común", "La aceptación expresa del Parlamento"]'::jsonb,2,'Art. 11 LF 11/2019 Navarra','Cuando se trate de órganos no vinculados jerárquicamente será necesaria la aprobación previa del superior común.',null),
('admin-navarra:12-fafc44cf43','admin-navarra',12,'¿Cuál de estas competencias es delegable según la Ley Foral 11/2019?','["La aprobación de disposiciones de carácter general", "La tramitación de expedientes de gestión ordinaria", "La revocación de actos de gravamen o desfavorables", "La resolución de recursos en el órgano que dictó el acto"]'::jsonb,1,'Art. 11 LF 11/2019 Navarra','No son delegables, entre otras, la aprobación de disposiciones generales, la resolución de recursos por el órgano autor del acto o la revocación de actos de gravamen.',null),
('admin-navarra:12-143a49626b','admin-navarra',12,'¿Dónde deben publicarse la delegación de competencias y su revocación?','["En el Boletín Oficial del Estado", "No requieren publicación", "En el Boletín Oficial de Navarra", "En el tablón del Departamento"]'::jsonb,2,'Art. 11 LF 11/2019 Navarra','La delegación y su revocación se aprueban por el órgano delegante y se publican en el BON.',null),
('admin-navarra:12-a78757de80','admin-navarra',12,'¿Qué requisito exige la eficacia de la delegación a favor de un organismo público?','["La autorización previa del Parlamento de Navarra", "La aceptación previa del organismo o, en su defecto, la aprobación del superior común", "Un convenio firmado con la entidad delegada y publicado en el Boletín Oficial de Navarra", "El informe preceptivo del Consejo de Navarra"]'::jsonb,1,'Art. 12 LF 11/2019 Navarra','Es necesaria la aceptación previa por parte del organismo o entidad; en su defecto, la aprobación previa del superior común.',null),
('admin-navarra:12-503ae0be0f','admin-navarra',12,'¿Cómo puede impugnarse el acuerdo de avocación según la Ley Foral 11/2019?','["Únicamente en el recurso contra la resolución del procedimiento", "Mediante recurso potestativo de reposición", "Mediante recurso de alzada autónomo", "No es impugnable en ningún caso"]'::jsonb,0,'Art. 13 LF 11/2019 Navarra','El acuerdo de avocación podrá impugnarse únicamente en el recurso que se interponga contra la resolución del procedimiento.',null),
('admin-navarra:12-2aa1ecbb6a','admin-navarra',12,'¿Cómo se formaliza la encomienda de gestión a un órgano de otro Departamento?','["Mediante convenio firmado por los dos Directores Generales y publicado en el BON", "Mediante acuerdo del Gobierno de Navarra", "Mediante orden foral del Departamento de Presidencia", "Mediante autorización conjunta de los titulares de ambos Departamentos"]'::jsonb,3,'Art. 14 LF 11/2019 Navarra','La encomienda a órgano de otro Departamento se hace mediante autorización conjunta de las personas titulares de ambos Departamentos.',null),
('admin-navarra:12-8d8706dcbc','admin-navarra',12,'¿Cómo se formaliza la encomienda de gestión a otra Administración Pública?','["Mediante autorización del Consejero", "Mediante la firma de un convenio", "Mediante contrato administrativo", "Mediante decreto foral"]'::jsonb,1,'Art. 14 LF 11/2019 Navarra','La encomienda a otra Administración se formaliza mediante convenio, una vez comprobada la existencia de crédito.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:12-4921e29499','admin-navarra',12,'¿Exige la delegación de firma su publicación en el BON para ser válida?','["Solo cuando afecte a varios Departamentos", "Sí, siempre", "No", "Sí, si la firma corresponde a un Consejero"]'::jsonb,2,'Art. 15 LF 11/2019 Navarra','La delegación de firma, para su validez, no exigirá su publicación en el BON.',null),
('admin-navarra:12-4f72d54ec2','admin-navarra',12,'¿Quién designa a quien suple temporalmente a un Director General?','["La persona titular del Departamento, mediante orden foral", "El propio Director General, mediante resolución", "El Gobierno de Navarra, mediante decreto foral", "La Secretaría General Técnica del Departamento"]'::jsonb,0,'Art. 16 LF 11/2019 Navarra','La persona titular de cada Departamento designa mediante orden foral a quien deba suplir a Directores Generales y Secretarios Generales Técnicos.',null),
('admin-navarra:12-ad6e40bda5','admin-navarra',12,'Si coexisten una suplencia de ámbito general y otra de ámbito específico, ¿cuál prevalece?','["La que se haya publicado en el BON", "La más antigua", "La de ámbito general", "La de ámbito específico"]'::jsonb,3,'Art. 16 LF 11/2019 Navarra','Se entiende que la de ámbito específico prevalece sobre la general, y ambas pueden quedar en suspenso por una para supuesto concreto.',null),
('admin-navarra:12-ad27868540','admin-navarra',12,'¿Quién resuelve los conflictos de atribuciones entre Departamentos de la Administración foral?','["El Presidente del Gobierno de Navarra", "El Gobierno de Navarra en pleno", "El Consejero de Presidencia", "El Consejo de Navarra"]'::jsonb,0,'Art. 17 LF 11/2019 Navarra','Los conflictos de atribuciones entre Departamentos son resueltos por la Presidenta o Presidente del Gobierno de Navarra.',null),
('admin-navarra:12-4f53223df7','admin-navarra',12,'¿Cuántas personas, como mínimo, forman un órgano colegiado de la Administración Pública Foral?','["Cuatro", "Tres", "Cinco", "Dos"]'::jsonb,1,'Art. 18 LF 11/2019 Navarra','Son órganos colegiados los formados por tres o más personas con funciones administrativas.',null),
('admin-navarra:12-cf26c48669','admin-navarra',12,'¿Cómo se crean los órganos colegiados que no tienen funciones decisorias, de propuesta, de informe preceptivo ni de control?','["Por ley foral", "Por decreto foral del Presidente", "Por acuerdo del Gobierno o por orden foral, como grupos o comisiones de trabajo", "Por resolución del Director General competente, publicada en el Boletín Oficial de Navarra"]'::jsonb,2,'Art. 19 LF 11/2019 Navarra','Tienen carácter de grupos o comisiones de trabajo y se crean por acuerdo del Gobierno o por orden foral; sus acuerdos no tienen efectos frente a terceros.',null),
('admin-navarra:12-0937358984','admin-navarra',12,'Si la persona que ejerce la Secretaría de un órgano colegiado no es miembro, ¿cómo asiste a las reuniones?','["Con voto solo para dirimir empates", "Con voz y con voto", "Sin voz ni voto", "Con voz y sin voto"]'::jsonb,3,'Art. 22 LF 11/2019 Navarra','Asiste con voz y voto si es miembro, o con voz y sin voto si no lo es.',null),
('admin-navarra:12-f043fb0896','admin-navarra',12,'¿Con qué antelación mínima se remiten las convocatorias de los órganos colegiados, salvo imposibilidad?','["Cinco días hábiles", "Setenta y dos horas", "Veinticuatro horas", "Cuarenta y ocho horas"]'::jsonb,3,'Art. 24 LF 11/2019 Navarra','Salvo que no resulte posible, se remiten con una antelación mínima de cuarenta y ocho horas por medios electrónicos.',null),
('admin-navarra:12-cb0ca21973','admin-navarra',12,'¿Qué asistencia exige la válida constitución de un órgano colegiado de la Administración foral?','["Presidente, Secretario y, al menos, la mitad de sus miembros", "Presidente y dos tercios de sus miembros", "Secretario y mayoría absoluta de los miembros, con o sin el Presidente", "Presidente, Secretario y un tercio de los miembros"]'::jsonb,0,'Art. 25 LF 11/2019 Navarra','Se requiere la asistencia del Presidente y del Secretario, o sus sustitutos, y de la mitad, al menos, de sus miembros.',null),
('admin-navarra:12-80aa80e661','admin-navarra',12,'¿Puede tratarse en un órgano colegiado un asunto que no figura en el orden del día?','["Nunca", "Sí, si asisten todos los miembros y la mayoría declara su urgencia", "Sí, si lo decide el Presidente", "Sí, si lo pide un tercio de los miembros con veinticuatro horas de antelación"]'::jsonb,1,'Art. 26 LF 11/2019 Navarra','Solo si asisten todos los miembros y se declara la urgencia por el voto favorable de la mayoría.',null),
('admin-navarra:12-900d7ebbbe','admin-navarra',12,'En los órganos colegiados de composición mixta, ¿es dirimente el voto del Presidente?','["Solo en segunda votación", "Sí, siempre", "No, salvo que lo establezcan sus normas de funcionamiento", "Solo si el Presidente pertenece a la Administración foral"]'::jsonb,2,'Art. 28 LF 11/2019 Navarra','En los de composición mixta, el voto del Presidente no es dirimente, excepto si así lo establecen sus normas de funcionamiento.',null),
('admin-navarra:12-7092340cc7','admin-navarra',12,'¿Quién crea y suprime los Departamentos de la Administración de la Comunidad Foral?','["El Parlamento, mediante ley foral", "El Gobierno de Navarra, mediante acuerdo", "El Presidente del Gobierno, mediante decreto foral", "El Consejero de Presidencia, mediante orden foral"]'::jsonb,2,'Art. 29 LF 11/2019 Navarra','Corresponde al Presidente del Gobierno de Navarra, mediante decreto foral.',null),
('admin-navarra:12-697666a81e','admin-navarra',12,'¿Quién crea las Direcciones Generales de la Administración foral?','["El Presidente del Gobierno, mediante decreto foral del Presidente", "El Gobierno de Navarra, mediante decreto foral, a propuesta del Consejero", "El Consejero, mediante orden foral", "El Parlamento de Navarra, mediante ley foral"]'::jsonb,1,'Art. 31 LF 11/2019 Navarra','Corresponde al Gobierno de Navarra, mediante decreto foral, a propuesta de la persona titular del Departamento.',null),
('admin-navarra:12-d11a549f88','admin-navarra',12,'¿Qué forma adoptan las decisiones administrativas de los Directores Generales?','["Resolución", "Acuerdo", "Decreto Foral", "Orden Foral"]'::jsonb,0,'Art. 32 LF 11/2019 Navarra','Sus decisiones adoptan la forma de resolución, firmada por la persona titular de la Dirección General.',null),
('admin-navarra:12-da56662e1c','admin-navarra',12,'¿Qué rango tienen las personas titulares de las Secretarías Generales Técnicas?','["Jefe de Sección", "Director General", "Consejero", "Director de Servicio"]'::jsonb,3,'Art. 33 LF 11/2019 Navarra','Tienen rango de Director de Servicio y se nombran por libre designación entre personal funcionario.',null),
('admin-navarra:12-bbd311ef57','admin-navarra',12,'¿Qué órgano informa jurídicamente, con carácter previo, la resolución de los recursos que se tramitan en el Departamento?','["La Sección de Régimen Jurídico de cada Servicio", "La Dirección General competente", "El Servicio de Asesoría Jurídica del Gobierno", "La Secretaría General Técnica"]'::jsonb,3,'Art. 33 LF 11/2019 Navarra','Las Secretarías Generales Técnicas informan con carácter previo, y desde el punto de vista jurídico, la resolución de los recursos.',null),
('admin-navarra:12-6605938668','admin-navarra',12,'¿Cómo se crean los Negociados de la Administración foral?','["Mediante resolución del Director General", "Mediante orden foral del titular del Departamento", "Mediante decreto foral del Presidente", "Mediante decreto foral del Gobierno"]'::jsonb,1,'Art. 34 LF 11/2019 Navarra','Los Negociados y unidades inferiores a la Sección se crean por orden foral; Servicios y Secciones, por decreto foral del Gobierno.',null),
('admin-navarra:12-ab4574c867','admin-navarra',12,'¿Cuál de estas entidades es un organismo público según la Ley Foral 11/2019?','["Un consorcio", "Una autoridad administrativa independiente", "Una entidad pública empresarial", "Una fundación pública"]'::jsonb,2,'Art. 38 LF 11/2019 Navarra','Los organismos públicos se clasifican en organismos autónomos y entidades públicas empresariales; consorcios y autoridades independientes son entidades de derecho público.',null),
('admin-navarra:12-1cf67b0841','admin-navarra',12,'¿Qué Departamento ejerce la supervisión continuada de las entidades del Sector Público Institucional Foral?','["El competente en materia de hacienda", "El competente en materia de función pública", "El competente en materia de Presidencia", "El Departamento al que están adscritas"]'::jsonb,0,'Art. 42 LF 11/2019 Navarra','La supervisión continuada la ejerce el Departamento competente en materia de hacienda; el control de eficacia, el de adscripción.',null),
('admin-navarra:12-b172ce34de','admin-navarra',12,'¿Qué potestad administrativa NO corresponde a los organismos públicos forales?','["La sancionadora", "La de revisión de oficio", "La expropiatoria", "La de autoorganización"]'::jsonb,2,'Art. 44 LF 11/2019 Navarra','Les corresponden las potestades necesarias para sus fines, salvo la potestad expropiatoria.',null),
('admin-navarra:13-c47e451474','admin-navarra',13,'Los actos administrativos producen efectos:','["Desde su publicación en el boletín oficial, salvo que en ellos se disponga otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa"]'::jsonb,2,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.',null),
('admin-navarra:13-58b63d81f4','admin-navarra',13,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["5 días desde que el acto se dictó", "15 días hábiles desde que el acto se dictó o se firmó", "1 mes desde que el acto se dictó", "10 días desde que el acto se dictó"]'::jsonb,3,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('admin-navarra:13-2dfafe5744','admin-navarra',13,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El Boletín Oficial del Estado", "El boletín oficial de la provincia", "Un periódico de tirada nacional"]'::jsonb,1,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('admin-navarra:13-0769506779','admin-navarra',13,'¿Cuál de estos actos es nulo de pleno derecho?','["El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin", "El dictado fuera del plazo establecido, cuando el término no sea esencial", "El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable"]'::jsonb,2,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.',null),
('admin-navarra:13-767432d918','admin-navarra',13,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Anulable", "Válido si se convalida", "Una irregularidad no invalidante", "Nulo de pleno derecho"]'::jsonb,3,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('admin-navarra:13-beca80bd7b','admin-navarra',13,'Los actos que incurren en desviación de poder son:','["Anulables", "Nulos de pleno derecho", "Válidos", "Inexistentes"]'::jsonb,0,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('admin-navarra:13-f7f70f5e00','admin-navarra',13,'El defecto de forma determina la anulabilidad del acto:','["Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el defecto de forma afecta a la motivación del acto, aunque no se haya producido indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('admin-navarra:13-0546713862','admin-navarra',13,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Nunca, ya que la actuación tardía es una mera irregularidad no invalidante", "Solo cuando lo imponga la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('admin-navarra:13-7e5f88a1e7','admin-navarra',13,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los inexistentes", "Cualquier acto", "Los anulables"]'::jsonb,3,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('admin-navarra:13-55a3a9e65c','admin-navarra',13,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Dictamen previo, preceptivo pero no vinculante, del Consejo de Estado u órgano consultivo equivalente autonómico", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración", "Informe favorable del servicio jurídico y audiencia previa de todos los interesados"]'::jsonb,0,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('admin-navarra:13-dd6c0be47d','admin-navarra',13,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["2 años", "4 años", "6 meses", "1 año"]'::jsonb,1,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('admin-navarra:13-8fb520bbf1','admin-navarra',13,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Los actos favorables", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables", "Las disposiciones generales"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('admin-navarra:13-5995e21321','admin-navarra',13,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "Solo antes de la notificación del acto, de oficio por el mismo órgano que lo dictó", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,3,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('admin-navarra:13-d85700c688','admin-navarra',13,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Alzada y extraordinario de revisión, únicamente", "Reposición obligatoria y alzada", "Súplica y potestativo de reposición"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('admin-navarra:13-096d8b6f99','admin-navarra',13,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "Suspende la ejecución del acto durante el plazo para resolver el recurso, salvo que el órgano acuerde lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null),
('admin-navarra:13-3286f21809','admin-navarra',13,'Si se solicita la suspensión de la ejecución al recurrir y no hay resolución expresa, la ejecución se entiende suspendida cuando pasa:','["10 días desde la solicitud", "15 días hábiles desde la solicitud", "1 mes desde la solicitud", "3 meses desde la solicitud"]'::jsonb,2,'Art. 117.3 Ley 39/2015','Se entiende suspendida si transcurre un mes desde la solicitud sin resolución expresa.',null),
('admin-navarra:13-3b4117202f','admin-navarra',13,'El recurso de alzada se interpone contra:','["Actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Disposiciones de carácter general y actos que no ponen fin a la vía administrativa", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el mismo órgano administrativo que los dictó", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico"]'::jsonb,3,'Art. 121.1 Ley 39/2015','Procede contra los actos que no ponen fin a la vía administrativa y se resuelve por el superior jerárquico.',null),
('admin-navarra:13-7a4b599d6b','admin-navarra',13,'Si el acto es expreso, el plazo para interponer recurso de alzada es de:','["1 mes", "2 meses", "15 días", "3 meses"]'::jsonb,0,'Art. 122.1 Ley 39/2015','Es de un mes si el acto es expreso; si no lo es, puede interponerse en cualquier momento desde el día siguiente a los efectos del silencio.',null),
('admin-navarra:13-1462f69b98','admin-navarra',13,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?','["1 mes; pasado ese plazo, se podrá entender estimado", "3 meses; pasado ese plazo, se podrá entender desestimado", "6 meses; pasado ese plazo, se podrá entender desestimado", "3 meses; pasado ese plazo sin resolución expresa, se entenderá siempre estimado"]'::jsonb,1,'Art. 122.2 Ley 39/2015','El plazo es de tres meses. Transcurrido sin resolución, se podrá entender desestimado el recurso, salvo excepción.',null),
('admin-navarra:13-7e22d61f76','admin-navarra',13,'El recurso de reposición:','["Es obligatorio antes de acudir a los tribunales contencioso-administrativos", "Es potestativo, contra actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico del que los dictó", "Es potestativo, contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Es obligatorio, contra actos que ponen fin a la vía administrativa, ante el mismo órgano"]'::jsonb,2,'Art. 123.1 Ley 39/2015','Es potestativo y se interpone ante el mismo órgano que dictó el acto que pone fin a la vía administrativa.',null),
('admin-navarra:13-287ec1efd2','admin-navarra',13,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de reposición?','["3 meses", "15 días", "2 meses", "1 mes"]'::jsonb,3,'Art. 124.2 Ley 39/2015','El plazo máximo es de un mes.',null),
('admin-navarra:13-cc031d0013','admin-navarra',13,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["4 años desde la notificación de la resolución", "3 meses desde la notificación de la resolución", "1 año desde la notificación de la resolución", "2 meses desde que se tuvo conocimiento del error"]'::jsonb,0,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('admin-navarra:13-bf0a0cc1f8','admin-navarra',13,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1", "Cabe un nuevo recurso de alzada ante el superior jerárquico del que resolvió", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1"]'::jsonb,1,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('admin-navarra:13-0661a90f0e','admin-navarra',13,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de un mes, con su informe y una copia completa y ordenada del expediente", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de quince días, sin necesidad de informe", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('admin-navarra:13-ba6dd05e25','admin-navarra',13,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["De un mes, prorrogable por otro mes a petición del interesado", "No inferior a diez días ni superior a quince", "No inferior a cinco días ni superior a diez", "De veinte días hábiles, prorrogable por otros diez"]'::jsonb,1,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('admin-navarra:13-1722264eb4','admin-navarra',13,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('admin-navarra:13-c553ad1b73','admin-navarra',13,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('admin-navarra:13-f7157144f1','admin-navarra',13,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Un cambio de criterio de la Administración posterior a la resolución", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null),
('admin-navarra:13-4925e7c2fe','admin-navarra',13,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Solo si el recurrente lo autoriza expresamente", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,3,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('admin-navarra:13-3861581f4d','admin-navarra',13,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de dos meses", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,3,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('admin-navarra:13-1131fe1548','admin-navarra',13,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Sea resuelto expresamente o se haya producido su desestimación presunta", "Pasen seis meses desde su interposición, aunque se haya resuelto antes", "Sea resuelto expresamente, sin que baste la desestimación presunta", "Lo autorice el órgano que dictó el acto"]'::jsonb,0,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('admin-navarra:13-774801a454','admin-navarra',13,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "La providencia de apertura del periodo de prueba", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,3,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.',null),
('admin-navarra:13-d1d49edf8a','admin-navarra',13,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('admin-navarra:13-a375bfc532','admin-navarra',13,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('admin-navarra:13-d3d3ccec4b','admin-navarra',13,'Contra las disposiciones administrativas de carácter general:','["No cabe recurso en vía administrativa", "Cabe recurso de alzada", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión"]'::jsonb,0,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('admin-navarra:13-530a67d43b','admin-navarra',13,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('admin-navarra:13-33b8398b7f','admin-navarra',13,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('admin-navarra:13-422cffc8bf','admin-navarra',13,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('admin-navarra:13-7d8996a755','admin-navarra',13,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.',null),
('admin-navarra:13-2443ca92d5','admin-navarra',13,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('admin-navarra:13-ae5b35d430','admin-navarra',13,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('admin-navarra:13-ab08428c30','admin-navarra',13,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('admin-navarra:13-9ba56dd304','admin-navarra',13,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('admin-navarra:13-7d624ccd49','admin-navarra',13,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('admin-navarra:13-3b7de63237','admin-navarra',13,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('admin-navarra:13-b947cdc9d1','admin-navarra',13,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('admin-navarra:13-a0067faf8f','admin-navarra',13,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('admin-navarra:13-c577738fad','admin-navarra',13,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('admin-navarra:13-2295559c1d','admin-navarra',13,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('admin-navarra:13-8dbb0a3ff8','admin-navarra',13,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('admin-navarra:13-0307ae42ee','admin-navarra',13,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('admin-navarra:13-a96ccb73fe','admin-navarra',13,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('admin-navarra:13-79774fb4cf','admin-navarra',13,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('admin-navarra:13-08b2ab637c','admin-navarra',13,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('admin-navarra:13-eb739dd77f','admin-navarra',13,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('admin-navarra:13-d4c7e67dcb','admin-navarra',13,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('admin-navarra:13-807fe84e3f','admin-navarra',13,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('admin-navarra:13-4176af4853','admin-navarra',13,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('admin-navarra:13-05e3328f82','admin-navarra',13,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('admin-navarra:13-ff9472ba97','admin-navarra',13,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('admin-navarra:13-629fda54a8','admin-navarra',13,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('admin-navarra:13-8b1a4f70ef','admin-navarra',13,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('admin-navarra:13-98c9a01de9','admin-navarra',13,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('admin-navarra:13-857b01b0d4','admin-navarra',13,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('admin-navarra:13-a4d75bd9b2','admin-navarra',13,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('admin-navarra:13-c281120586','admin-navarra',13,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('admin-navarra:13-9549be1059','admin-navarra',13,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('admin-navarra:13-eae84cf366','admin-navarra',13,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('admin-navarra:13-f32d23e5d2','admin-navarra',13,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.',null),
('admin-navarra:13-00854b5949','admin-navarra',13,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('admin-navarra:13-60b618986f','admin-navarra',13,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('admin-navarra:13-58bc94d8c6','admin-navarra',13,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.',null),
('admin-navarra:13-81652276d8','admin-navarra',13,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('admin-navarra:13-f53a03784a','admin-navarra',13,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('admin-navarra:13-6867a3bb34','admin-navarra',13,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('admin-navarra:13-79c5b0f4fe','admin-navarra',13,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('admin-navarra:13-26aac53042','admin-navarra',13,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('admin-navarra:13-e44c730e46','admin-navarra',13,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('admin-navarra:13-0bf4f9a9d0','admin-navarra',13,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('admin-navarra:13-6361a72e7a','admin-navarra',13,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Un mes a partir de la fecha en que el acto haya sido dictado y firmado", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,2,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('admin-navarra:13-c746b0f3b7','admin-navarra',13,'Además de los previstos en la legislación básica, ¿qué actos ponen fin a la vía administrativa en la Administración foral?','["Los de los Secretarios Generales Técnicos", "Los del Gobierno de Navarra y de su Presidente", "Los de los Jefes de Servicio", "Los de los Directores Generales en todo caso"]'::jsonb,1,'Art. 119 LF 11/2019 Navarra','Ponen fin a la vía administrativa, entre otros, los actos del Gobierno de Navarra y de su Presidente.',null),
('admin-navarra:13-e17e3c775a','admin-navarra',13,'¿A quién se atribuyen, a efectos de recurso, los actos de los órganos colegiados de la Administración foral distintos del Gobierno?','["A su Secretario", "Al pleno del órgano", "Al Consejero de adscripción", "A su Presidente"]'::jsonb,3,'Art. 119 LF 11/2019 Navarra','Los actos de los órganos colegiados, salvo los del Gobierno, se consideran dictados por su Presidente a efectos de recursos.',null),
('admin-navarra:13-74b1d40d86','admin-navarra',13,'¿Quién resuelve la revisión de oficio de un acto nulo dictado por un órgano de un Departamento foral?','["La persona titular del Departamento", "El Gobierno de Navarra en todo caso", "El propio órgano autor del acto", "El Consejo de Navarra"]'::jsonb,0,'Art. 123 LF 11/2019 Navarra','La inicia el órgano autor y la resuelve la persona titular del Departamento, salvo actos del Gobierno, que resuelve este.',null),
('admin-navarra:13-408ffc75bc','admin-navarra',13,'¿Qué dictamen exige la declaración de nulidad de actos de la Administración Pública Foral?','["Dictamen previo y favorable del Consejo de Navarra", "Informe de la Cámara de Comptos", "Dictamen del Consejo de Estado", "Informe de la Secretaría General Técnica"]'::jsonb,0,'Art. 123 LF 11/2019 Navarra','La declaración de nulidad requiere dictamen previo y favorable del Consejo de Navarra.',null),
('admin-navarra:13-6137a38d5e','admin-navarra',13,'¿Quién declara la lesividad de un acto anulable dictado por el Gobierno de Navarra?','["El Consejero de Presidencia", "El Parlamento de Navarra", "El propio Gobierno de Navarra", "El Tribunal Superior de Justicia"]'::jsonb,2,'Art. 124 LF 11/2019 Navarra','Corresponde al titular del Departamento del órgano autor; si el acto es del Gobierno, al propio Gobierno.',null),
('admin-navarra:13-6573fb5877','admin-navarra',13,'¿Quién puede corregir las erratas del texto publicado en el BON respecto del texto recibido?','["Cualquier interesado mediante escrito", "El órgano encargado del Boletín, comunicándolo antes al órgano autor", "Solo el órgano que dictó la disposición", "El Gobierno de Navarra mediante acuerdo"]'::jsonb,1,'Art. 125 LF 11/2019 Navarra','Las erratas pueden ser corregidas por el órgano encargado del Boletín, comunicándolo previamente al órgano del que emanó el acto.',null),
('admin-navarra:13-9433194313','admin-navarra',13,'¿Ante quién se interpone el recurso de alzada contra los actos de un Consejero del Gobierno de Navarra?','["Ante el Presidente del Gobierno", "Ante el Consejo de Navarra", "Ante el Parlamento de Navarra", "Ante el Gobierno de Navarra"]'::jsonb,3,'Art. 126 LF 11/2019 Navarra','El Gobierno de Navarra es órgano superior jerárquico respecto de los actos de los Consejeros.',null),
('admin-navarra:13-8144442bac','admin-navarra',13,'¿Ante quién se recurren en alzada los actos en materia de función pública dictados por órganos inferiores a Consejero?','["Ante el Gobierno de Navarra", "Ante la Comisión de Personal", "Ante el titular del Departamento competente en materia de función pública", "Ante el titular del Departamento del órgano autor"]'::jsonb,2,'Art. 126 LF 11/2019 Navarra','En materia de función pública, el superior jerárquico es el titular del Departamento competente en esa materia.',null),
('admin-navarra:13-994546ffdb','admin-navarra',13,'¿Ante quién se recurren en alzada los actos de un tribunal de selección de personal de la Administración foral?','["Ante el propio tribunal en reposición", "Ante el Director General de Función Pública en todo caso", "Ante el Gobierno de Navarra", "Ante el órgano que nombró a su presidente"]'::jsonb,3,'Art. 126 LF 11/2019 Navarra','Se recurren en alzada ante la autoridad u órgano que haya nombrado al presidente del tribunal.',null),
('admin-navarra:13-f6c478a95a','admin-navarra',13,'¿Cómo pueden sustituirse los recursos de alzada y reposición por otros procedimientos en la Administración foral?','["Solo por ley foral, en supuestos o ámbitos sectoriales determinados", "Por acuerdo entre las partes", "Por orden foral de cada Departamento", "Por decreto foral del Gobierno"]'::jsonb,0,'Art. 127 LF 11/2019 Navarra','La sustitución únicamente puede hacerse por ley foral en supuestos o ámbitos determinados.',null),
('admin-navarra:14-32592fa6ff','admin-navarra',14,'¿Cuál es el plazo máximo para resolver que puede fijar una norma reguladora de un procedimiento?','["3 meses, salvo que una norma con rango de ley establezca uno mayor", "6 meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE", "1 año, salvo que una norma con rango de ley o el Derecho de la Unión Europea establezcan uno menor", "6 meses, sin excepción, cualquiera que sea el rango de la norma reguladora"]'::jsonb,1,'Art. 21.2 Ley 39/2015','El plazo no puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE.',null),
('admin-navarra:14-714eef452e','admin-navarra',14,'Si la norma reguladora de un procedimiento no fija plazo máximo para resolver, este será de:','["1 mes", "6 meses", "3 meses", "10 días"]'::jsonb,2,'Art. 21.3 Ley 39/2015','Cuando las normas no fijen el plazo máximo, será de tres meses.',null),
('admin-navarra:14-bd401906a2','admin-navarra',14,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Causa de caducidad del procedimiento", "Desestimatorio, sin excepción", "Estimatorio, salvo las excepciones legales"]'::jsonb,3,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('admin-navarra:14-9f966f6f22','admin-navarra',14,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La caducidad", "La estimación por silencio", "La desestimación por silencio", "La prórroga automática del plazo"]'::jsonb,0,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('admin-navarra:14-46dc5af85b','admin-navarra',14,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('admin-navarra:14-585ffb8106','admin-navarra',14,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('admin-navarra:14-2e6cbc2a4d','admin-navarra',14,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('admin-navarra:14-ff7ee2e48f','admin-navarra',14,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('admin-navarra:14-16469dfe0d','admin-navarra',14,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('admin-navarra:14-0000700573','admin-navarra',14,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.',null),
('admin-navarra:14-e2fc39bce9','admin-navarra',14,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.',null),
('admin-navarra:14-2f0e1f63f6','admin-navarra',14,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('admin-navarra:14-c790680690','admin-navarra',14,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('admin-navarra:14-36ad272a48','admin-navarra',14,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('admin-navarra:14-8e1a86e3b1','admin-navarra',14,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.',null),
('admin-navarra:14-d97380537a','admin-navarra',14,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.',null),
('admin-navarra:14-015edbe38e','admin-navarra',14,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('admin-navarra:14-e6dab75715','admin-navarra',14,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('admin-navarra:14-dde74bdef2','admin-navarra',14,'Cada Administración debe mantener, para los documentos electrónicos de procedimientos finalizados:','["Un archivo en papel", "Un archivo electrónico único", "Un archivo por cada funcionario", "Copias en el BOE"]'::jsonb,1,'Art. 17.1 Ley 39/2015','Debe mantener un archivo electrónico único de los documentos electrónicos de procedimientos finalizados.',null),
('admin-navarra:14-a3c68a87b2','admin-navarra',14,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó", "A las 9 horas del tercer día hábil siguiente"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('admin-navarra:14-f916154fd4','admin-navarra',14,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('admin-navarra:14-8c039a8451','admin-navarra',14,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('admin-navarra:14-28138c1e06','admin-navarra',14,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('admin-navarra:14-5f115f2bd6','admin-navarra',14,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('admin-navarra:14-ef96c9936a','admin-navarra',14,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Acto administrativo finalizador del procedimiento", "Acto de trámite cualificado, recurrible en alzada", "Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa"]'::jsonb,0,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('admin-navarra:14-bbd11485ad','admin-navarra',14,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('admin-navarra:14-b7bfc7296e','admin-navarra',14,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('admin-navarra:14-daf48106f8','admin-navarra',14,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('admin-navarra:14-30c27747b9','admin-navarra',14,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('admin-navarra:14-1eb84d8e49','admin-navarra',14,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('admin-navarra:14-a8e6c4162f','admin-navarra',14,'Los titulares de las unidades administrativas que tengan a su cargo la resolución o despacho de los asuntos:','["Serán responsables directos de su tramitación y adoptarán las medidas para remover los obstáculos que retrasen el ejercicio de los derechos de los interesados", "No tienen responsabilidad directa sobre la tramitación, que corresponde en exclusiva al titular del órgano superior jerárquico del que dependan", "Responden solo ante los tribunales penales", "Solo son responsables si lo solicita el interesado"]'::jsonb,0,'Art. 20.1 Ley 39/2015','Son responsables directos de la tramitación.',null),
('admin-navarra:14-f76588e523','admin-navarra',14,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('admin-navarra:14-40b7f59438','admin-navarra',14,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('admin-navarra:14-02498a81cf','admin-navarra',14,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('admin-navarra:14-7a84f6a974','admin-navarra',14,'La comparecencia de las personas ante las oficinas públicas solo será obligatoria cuando:','["El interesado tenga más de 65 años", "Lo establezca una circular o instrucción interna del órgano", "Lo decida motivadamente el instructor del procedimiento", "Así esté previsto en una norma con rango de ley"]'::jsonb,3,'Art. 19.1 Ley 39/2015','Solo es obligatoria si una norma con rango de ley lo prevé.',null),
('admin-navarra:14-26aa05a119','admin-navarra',14,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('admin-navarra:14-1f7cc479ad','admin-navarra',14,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('admin-navarra:14-c6781c23b8','admin-navarra',14,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null)
